# 숫자만 달라졌을 뿐 실제 크기의 폭은 그대로다.
UI_FONT = "Malgun Gothic"     # 시작할 때 프리텐다드가 실리면 바뀐다


def load_ui_font(char_dir):
    """파츠에 실린 프리텐다드를 이 프로세스에만 등록한다 (설치 불필요).

    글꼴 모양·자간이 맥(애플 SD 고딕 Neo)과 비슷해진다. 파일이 없거나
    실패하면 맑은 고딕 그대로. 맥은 시스템 글꼴이 이미 그 모습이라 안 바꾼다.
    """
    global UI_FONT
    if not IS_WIN:
        if IS_MAC:
            # '맑은 고딕'은 맥에 없다 — 없는 이름을 주면 Tk 가 **없는
            # 글꼴의 메트릭**으로 세로 중앙을 잡고 글리프는 대체 글꼴로
            # 그려서, 글자가 알약보다 몇 px 아래로 쏠린다 (사가 제보 —
            # CI 맥 러너 캡처로 재현). ♥ 같은 기호가 깨져 보이는 것도
            # 같은 뿌리다. 모든 맥에 있는 한글 글꼴을 준다.
            UI_FONT = "Apple SD Gothic Neo"
        return
    try:
        d = os.path.join(char_dir, "fonts")
        if not os.path.isdir(d):
            return
        g = ctypes.WinDLL("gdi32")    # 지뢰 21 — 공용 windll 은 안 건드린다
        g.AddFontResourceExW.argtypes = (ctypes.c_wchar_p, ctypes.c_uint32,
                                         ctypes.c_void_p)
        g.AddFontResourceExW.restype = ctypes.c_int
        got = 0
        for f in sorted(os.listdir(d)):
            if f.lower().endswith((".ttf", ".otf")):
                got += g.AddFontResourceExW(os.path.join(d, f),
                                            0x10, None)      # FR_PRIVATE
        if got:
            UI_FONT = "Pretendard"
    except Exception:
        pass


FONT_SPAN = 1.6
FONT_MIN, FONT_MAX = 45, 100
DOT_OTHER = "#f0b95e"     # 딴짓 중(작업앱 아님) 표시색


class _POINT(ctypes.Structure):
    _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]


class _RECT(ctypes.Structure):
    _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                ("right", ctypes.c_long), ("bottom", ctypes.c_long)]


class _MONITORINFO(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_ulong), ("rcMonitor", _RECT),
                ("rcWork", _RECT), ("dwFlags", ctypes.c_ulong)]


class _LASTINPUTINFO(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_uint), ("dwTime", ctypes.c_uint)]


class _SIZE(ctypes.Structure):
    _fields_ = [("cx", ctypes.c_long), ("cy", ctypes.c_long)]


class _BLENDFUNCTION(ctypes.Structure):
    _fields_ = [("BlendOp", ctypes.c_byte), ("BlendFlags", ctypes.c_byte),
                ("SourceConstantAlpha", ctypes.c_byte), ("AlphaFormat", ctypes.c_byte)]


class _BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [("biSize", ctypes.c_uint32), ("biWidth", ctypes.c_long),
                ("biHeight", ctypes.c_long), ("biPlanes", ctypes.c_uint16),
                ("biBitCount", ctypes.c_uint16), ("biCompression", ctypes.c_uint32),
                ("biSizeImage", ctypes.c_uint32), ("biXPelsPerMeter", ctypes.c_long),
                ("biYPelsPerMeter", ctypes.c_long), ("biClrUsed", ctypes.c_uint32),
                ("biClrImportant", ctypes.c_uint32)]


def _layer_api():
    """레이어드 창에 쓸 Win32 함수들 — 인자·반환 형을 제대로 지정해서 돌려준다.

    64비트에서 핸들(HDC/HWND)은 c_int로 잘린다. 실측: GetDC(0)이 형을 안
    정하면 1291916892로, 지정하면 18446744073625737419로 나온다. 잘린 손잡이를
    넘기면 UpdateLayeredWindow가 아무 말 없이 실패한다 — 창이 그 자리에 그대로
    있고 그림도 안 바뀌어서, 겉으로는 '이펙트가 안 보인다'로만 보인다.

    ctypes.windll은 프로세스가 공유하는 객체라 거기에 형을 지정하면 같은
    함수를 쓰는 다른 코드까지 묶인다(스티커에서 겪은 일). 그래서 여기서만
    쓸 핸들을 따로 연다.
    """
    import ctypes.wintypes as wt
    u = ctypes.WinDLL("user32", use_last_error=True)
    g = ctypes.WinDLL("gdi32", use_last_error=True)
    u.GetDC.restype, u.GetDC.argtypes = wt.HDC, [wt.HWND]
    u.ReleaseDC.restype = ctypes.c_int
    u.ReleaseDC.argtypes = [wt.HWND, wt.HDC]
    u.GetWindowLongW.restype = ctypes.c_long
    u.GetWindowLongW.argtypes = [wt.HWND, ctypes.c_int]
    u.SetWindowLongW.restype = ctypes.c_long
    u.SetWindowLongW.argtypes = [wt.HWND, ctypes.c_int, ctypes.c_long]
    u.ShowWindow.argtypes = [wt.HWND, ctypes.c_int]
    u.SetWindowPos.argtypes = [wt.HWND, wt.HWND, ctypes.c_int, ctypes.c_int,
                               ctypes.c_int, ctypes.c_int, ctypes.c_uint]
    u.UpdateLayeredWindow.restype = wt.BOOL
    u.UpdateLayeredWindow.argtypes = [
        wt.HWND, wt.HDC, ctypes.POINTER(_POINT), ctypes.POINTER(_SIZE),
        wt.HDC, ctypes.POINTER(_POINT), wt.DWORD,
        ctypes.POINTER(_BLENDFUNCTION), wt.DWORD]
    g.CreateCompatibleDC.restype, g.CreateCompatibleDC.argtypes = wt.HDC, [wt.HDC]
    g.CreateDIBSection.restype = wt.HBITMAP
    g.CreateDIBSection.argtypes = [wt.HDC, ctypes.c_void_p, ctypes.c_uint,
                                   ctypes.POINTER(ctypes.c_void_p),
                                   wt.HANDLE, wt.DWORD]
    g.SelectObject.restype, g.SelectObject.argtypes = wt.HGDIOBJ, [wt.HDC,
                                                                   wt.HGDIOBJ]
    g.DeleteObject.argtypes = [wt.HGDIOBJ]
    g.DeleteDC.argtypes = [wt.HDC]
    return u, g


_LAYER_U = _LAYER_G = None


def layer_api():
    """레이어드 창용 Win32 묶음 (한 번만 만든다). 윈도우가 아니면 (None, None)."""
    global _LAYER_U, _LAYER_G
    if _LAYER_U is None and IS_WIN:
        try:
            _LAYER_U, _LAYER_G = _layer_api()
        except Exception:
            _LAYER_U = _LAYER_G = False
    if not _LAYER_U:
        return None, None
    return _LAYER_U, _LAYER_G


class ShadowLayer:
    """캐릭터 창 뒤에 깔리는 진짜 반투명 그림자 (per-pixel alpha 레이어 창).

    색상키 투명창은 반투명을 표현할 수 없으므로, 그림자만 별도의
    UpdateLayeredWindow 창으로 그린다. 클릭은 통과(WS_EX_TRANSPARENT).
    """

    def __init__(self, root, image, offset=(7, 9)):
        self.offset = offset
        self.top = tk.Toplevel(root)
        self.top.overrideredirect(True)
        self.top.attributes("-topmost", True)
        self.top.update_idletasks()
        self.hwnd = int(self.top.wm_frame(), 16)
        u, _g = layer_api()
        GWL_EXSTYLE = -20
        ex = u.GetWindowLongW(self.hwnd, GWL_EXSTYLE)
        # LAYERED | TRANSPARENT(클릭 통과) | TOOLWINDOW | NOACTIVATE
        u.SetWindowLongW(self.hwnd, GWL_EXSTYLE,
                         ex | 0x80000 | 0x20 | 0x80 | 0x8000000)
        self._push(image)

    def _push(self, im):
        """BGRA 비트맵을 레이어 창에 업로드 (그림자는 검정이라 premultiply 불요).

        형을 지정한 묶음을 쓴다 — 안 그러면 64비트 핸들이 잘려 이 호출이
        조용히 실패한다(그림자가 안 보인다).
        """
        u, g = layer_api()
        if u is None:
            return
        w, h = im.size
        data = im.tobytes("raw", "BGRA")
        hdc = u.GetDC(0)
        mem = g.CreateCompatibleDC(hdc)
        bmi = _BITMAPINFOHEADER()
        bmi.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
        bmi.biWidth, bmi.biHeight = w, -h
        bmi.biPlanes, bmi.biBitCount = 1, 32
        bits = ctypes.c_void_p()
        hbm = g.CreateDIBSection(hdc, ctypes.byref(bmi), 0,
                                 ctypes.byref(bits), None, 0)
        ctypes.memmove(bits, data, len(data))
        old = g.SelectObject(mem, hbm)
        blend = _BLENDFUNCTION(0, 0, 255, 1)  # AC_SRC_OVER, alpha 채널 사용
        # 세 번째 인자는 '창을 옮길 새 화면 좌표'다. (0,0)을 넘기면 이미지를
        # 바꿀 때마다 그림자 창이 화면 좌상단으로 튀어 사라진 것처럼 보인다.
        # 위치를 바꿀 생각이 없으므로 NULL을 넘겨 그대로 둔다.
        u.UpdateLayeredWindow(self.hwnd, hdc, None,
                              ctypes.byref(_SIZE(w, h)), mem,
                              ctypes.byref(_POINT(0, 0)), 0,
                              ctypes.byref(blend), 2)  # ULW_ALPHA
        g.SelectObject(mem, old)
        g.DeleteObject(hbm)
        g.DeleteDC(mem)
        u.ReleaseDC(0, hdc)

    def set_image(self, image):
        """그림자 이미지 교체 (시계 토글로 크기가 바뀔 때)."""
        self._push(image)

    def show(self, on):
        """그림자를 보였다 숨겼다 (상태 칩 '자리비움').

        캐릭터만 안 그리면 그림자는 그대로 남아 회색 덩어리가 뜬다
        (찍어서 확인). 창째로 숨긴다.
        """
        u, _g = layer_api()
        if u is None:
            return
        try:
            u.ShowWindow(self.hwnd, 5 if on else 0)   # SW_SHOW / SW_HIDE
        except Exception:
            pass

    def set_topmost(self, on):
        """이 레이어의 '항상 위'를 켜고 끈다.

        캐릭터만 내리면 z 그룹이 갈려 이 창이 캐릭터 위로 올라온다.
        """
        u, _g = layer_api()
        if u is None:
            return
        try:
            u.SetWindowPos(self.hwnd, -1 if on else -2, 0, 0, 0, 0,
                           0x1 | 0x2 | 0x10)     # NOSIZE|NOMOVE|NOACTIVATE
        except Exception:
            pass

    def place(self, x, y, owner_hwnd):
        """본체 창 바로 아래 z순서로, 오프셋만큼 밀린 위치에 배치."""
        SWP_NOSIZE, SWP_NOACTIVATE = 0x1, 0x10
        u, _g = layer_api()
        if u is None:
            return
        u.SetWindowPos(self.hwnd, owner_hwnd,
                       x + self.offset[0], y + self.offset[1],
                       0, 0, SWP_NOSIZE | SWP_NOACTIVATE)


class FxLayer:
    """파티클(음표·하트·땀…)을 진짜 반투명으로 그리는 레이어 창.

    색상키 투명창은 반투명을 못 낸다. 그래서 지금까지는 옅어지는 대신 픽셀을
    무작위로 솎아내 사라지게 했는데, 그게 '모래처럼 부서진다'는 그 모습이다.
    그림자와 같은 UpdateLayeredWindow 창을 캐릭터 위에 하나 더 두면 알파가
    그대로 나와 부드럽게 사라진다. 클릭은 통과한다. 윈도우 전용.

    파티클이 있는 동안만 보이고, 없으면 숨겨 둔다(그때는 비용이 0이다).
    """

    def set_topmost(self, on):
        """이 레이어의 '항상 위'를 켜고 끈다 (그림자와 같은 이유)."""
        u, _g = layer_api()
        if u is None:
            return
        try:
            u.SetWindowPos(self.hwnd, -1 if on else -2, 0, 0, 0, 0,
                           0x1 | 0x2 | 0x10)
        except Exception:
            pass

    def __init__(self, root):
        self.ok = False
        self.hwnd = 0
        self._shown = False
        self.top = tk.Toplevel(root)
        self.top.overrideredirect(True)
        self.top.attributes("-topmost", True)
        self.top.update_idletasks()
        self.hwnd = int(self.top.wm_frame(), 16)
        u, _g = layer_api()
        if u is None:
            return
        GWL_EXSTYLE = -20
        ex = u.GetWindowLongW(self.hwnd, GWL_EXSTYLE)
        # LAYERED | TRANSPARENT(클릭 통과) | TOOLWINDOW | NOACTIVATE
        u.SetWindowLongW(self.hwnd, GWL_EXSTYLE,
                         ex | 0x80000 | 0x20 | 0x80 | 0x8000000)
        # 숨기지 않는다. UpdateLayeredWindow는 '숨겨진 창'에 대고 부르면
        # 오류 87(잘못된 매개변수)로 실패한다 — 실측으로 확인했다.
        # 대신 1x1 투명 그림을 올려 둔다. 창은 살아 있지만 아무것도 안 보인다.
        self._shown = True
        self.show(Image.new("RGBA", (1, 1), (0, 0, 0, 0)), 0, 0)
        self.ok = True

    @staticmethod
    def _premul(im):
        """알파 미리곱한 BGRA 바이트.

        UpdateLayeredWindow는 색이 알파로 미리 곱해져 있다고 가정한다.
        그냥 넘기면 반투명한 곳이 허옇게 뜬다(그림자는 검정이라 티가 안 났다).
        """
        from PIL import ImageChops
        r, g, b, a = im.convert("RGBA").split()
        # 메모리에 B,G,R,A 순으로 놓이도록 그 순서로 합친다
        pm = Image.merge("RGBA", (ImageChops.multiply(b, a),
                                  ImageChops.multiply(g, a),
                                  ImageChops.multiply(r, a), a))
        return pm.tobytes("raw", "RGBA")

    def hide(self):
        u, _g = layer_api()
        if self._shown and self.hwnd and u is not None:
            u.ShowWindow(self.hwnd, 0)
            self._shown = False

    def show(self, im, x, y):
        """그림을 화면 (x, y)에 올린다. 늘 맨 앞(캐릭터 위)으로 올린다."""
        u, g = layer_api()
        if u is None:
            return
        w, h = im.size
        if w <= 0 or h <= 0:
            self.hide()
            return
        if not self._shown:
            # 숨은 채로 UpdateLayeredWindow를 부르면 오류 87로 실패한다.
            # 반드시 먼저 보이게 한 다음 그린다.
            u.ShowWindow(self.hwnd, 4)           # SW_SHOWNOACTIVATE
            self._shown = True
        data = self._premul(im)
        hdc = u.GetDC(0)
        mem = g.CreateCompatibleDC(hdc)
        bmi = _BITMAPINFOHEADER()
        bmi.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
        bmi.biWidth, bmi.biHeight = w, -h        # 위에서 아래로
        bmi.biPlanes, bmi.biBitCount = 1, 32
        bits = ctypes.c_void_p()
        hbm = g.CreateDIBSection(hdc, ctypes.byref(bmi), 0,
                                 ctypes.byref(bits), None, 0)
        ctypes.memmove(bits, data, len(data))
        old = g.SelectObject(mem, hbm)
        blend = _BLENDFUNCTION(0, 0, 255, 1)     # AC_SRC_OVER, 알파 사용
        # 자리·크기·그림을 한 번에 — 따로 옮기면 한 프레임 어긋난다
        u.UpdateLayeredWindow(self.hwnd, hdc, ctypes.byref(_POINT(int(x), int(y))),
                              ctypes.byref(_SIZE(w, h)), mem,
                              ctypes.byref(_POINT(0, 0)), 0,
                              ctypes.byref(blend), 2)   # ULW_ALPHA
        g.SelectObject(mem, old)
        g.DeleteObject(hbm)
        g.DeleteDC(mem)
        u.ReleaseDC(0, hdc)
        # 맨 앞으로. 둘째 인자는 '이 창 뒤에 놓아라'라는 뜻이라 캐릭터 핸들을
        # 넘기면 파티클이 캐릭터 뒤로 가서 가려진다. 그리고 HWND_TOPMOST(-1)는
        # 이미 '항상 위'인 창에는 아무 일도 하지 않아 순서를 못 되돌린다.
        # HWND_TOP(0)이라야 항상 위 무리의 맨 앞으로 올라온다(말풍선과 같은 방식).
        # 캐릭터를 누르면 그 창이 앞으로 나오므로 프레임마다 다시 올린다.
        SWP_NOSIZE, SWP_NOMOVE, SWP_NOACTIVATE = 0x1, 0x2, 0x10
        u.SetWindowPos(self.hwnd, 0, 0, 0, 0, 0,
                       SWP_NOSIZE | SWP_NOMOVE | SWP_NOACTIVATE)

    def destroy(self):
        try:
            self.top.destroy()
        except Exception:
            pass
        self.hwnd = 0
        self.ok = False


class MacDim:
    """감시 때 화면 전체를 살짝 어둡게 — 맥판 (FxLayer 짝의 show/hide).

    UpdateLayeredWindow 가 없으니 검은 Tk 창에 **창 알파**를 준다 (0.42 ≈
    윈도우의 110/255). 클릭은 AppKit `setIgnoresMouseEvents:` 로
    통과시키는데, **확인이 안 되면 절대 보이지 않는다** — 화면 전체를
    덮는 창이 클릭을 먹으면 컴퓨터를 못 쓰게 된다. 켜고 끄는 것은 창을
    만들었다 지우는 대신 알파 0↔0.42 로 한다 (합성 필터·창 순서가 얽히는
    일을 줄인다).
    """

    def __init__(self, root):
        self.ok = False
        self.top = None
        try:
            top = tk.Toplevel(root)
            top.overrideredirect(True)
            top.attributes("-topmost", True)
            top.configure(bg="#000000", bd=0, highlightthickness=0)
            top.attributes("-alpha", 0.0)          # 확인 전에는 안 보인다
            sw = top.winfo_screenwidth()
            sh = top.winfo_screenheight()
            top.geometry("%dx%d+0+0" % (sw, sh))
            top.update_idletasks()
            self.top = top
            if not self._click_through(sw, sh):
                top.destroy()                       # 어중간 금지 (지뢰 119)
                self.top = None
                return
            self.ok = True
        except Exception:
            try:
                if self.top is not None:
                    self.top.destroy()
            except Exception:
                pass
            self.top = None

    @staticmethod
    def _click_through(sw, sh):
        """화면 크기의 우리 창을 찾아 클릭 통과를 걸고 **확인까지** 한다.

        창 대조는 pyobjc 의 frame() 으로 한다 — ctypes msgSend 로 구조체를
        받으면 죽을 수 있다 (지뢰 130). 메뉴 막대 때문에 세로가 조금 깎일
        수 있어 높이는 느슨하게 본다.
        """
        try:
            from AppKit import NSApp
            for w in NSApp.windows():
                try:
                    sz = w.frame().size
                    if (abs(sz.width - sw) <= 4
                            and abs(sz.height - sh) <= 48):
                        w.setIgnoresMouseEvents_(True)
                        if bool(w.ignoresMouseEvents()):
                            return True
                except Exception:
                    pass
        except Exception:
            pass
        return False

    def show(self):
        try:
            if self.top is not None and self.top.winfo_exists():
                self.top.attributes("-alpha", 0.42)
                self.top.lift()
        except Exception:
            pass

    def hide(self):
        try:
            if self.top is not None and self.top.winfo_exists():
                self.top.attributes("-alpha", 0.0)
        except Exception:
            pass


class CharLayer:
    """캐릭터 몸을 진짜 반투명으로 그리는 레이어 창 (본체 창 **뒤**).

    색상키 투명창은 픽셀이 켜짐/꺼짐 둘뿐이라 부드러운 선을 못 담는다.
    그래서 지금까지는 가장자리를 일부러 이분화해 왔고(hard_alpha), 그것이
    '도트처럼 깨져 보인다'는 그 모습이다 (지뢰 31·65). 몸만 그림자·파티클과
    같은 UpdateLayeredWindow 창으로 옮기면 원본 알파가 그대로 나온다.

    **본체 창 뒤에 두는 것이 요점이다.** 카드·말풍선·모자·연출은 캔버스에
    그대로 두는데, 이 창이 뒤에 있으므로 그것들이 저절로 캐릭터 위에 온다 —
    그리는 차례가 지금 그대로 지켜진다 (실측: 카드와 캐릭터가 겹치는 넓이는
    0px²이고, 캐릭터 위에 얹는 것들만 겹친다).

    클릭은 통과시키지 않는다 (WS_EX_TRANSPARENT 를 **안** 건다). 캔버스에서
    몸을 지우면 그 자리는 색상키라 클릭이 뒤로 빠지는데, 그 클릭을 이 창이
    받아 본체의 핸들러로 넘긴다. 알파 0인 자리는 레이어 창이 알아서
    통과시키므로 '몸을 눌렀을 때만' 반응하는 지금 성질이 그대로 남는다.
    """

    def __init__(self, root):
        self.ok = False
        self.hwnd = 0
        self._shown = False
        self.top = tk.Toplevel(root)
        self.top.overrideredirect(True)
        self.top.attributes("-topmost", True)
        self.top.update_idletasks()
        self.hwnd = int(self.top.wm_frame(), 16)
        u, _g = layer_api()
        if u is None:
            return
        GWL_EXSTYLE = -20
        ex = u.GetWindowLongW(self.hwnd, GWL_EXSTYLE)
        # LAYERED | TOOLWINDOW | NOACTIVATE.
        # TRANSPARENT(0x20)는 **안 건다** — 몸을 눌러야 하기 때문이다.
        u.SetWindowLongW(self.hwnd, GWL_EXSTYLE,
                         ex | 0x80000 | 0x80 | 0x8000000)
        # 숨긴 창에 대고 UpdateLayeredWindow 를 부르면 오류 87 로 조용히
        # 실패한다 (지뢰 23). 파티클과 같이 1x1 투명을 올려 둔다.
        self._shown = True
        self.push(Image.new("RGBA", (1, 1), (0, 0, 0, 0)), 0, 0)
        self.ok = True

    _FAST = [True]               # PIL 의 premultiplied 모드를 쓸 수 있는가

    @classmethod
    def _premul(cls, im):
        """알파 미리곱한 BGRA 바이트 (지뢰 117).

        PIL 에 premultiplied 모드('RGBa')가 있어서 한 번에 바꿀 수 있다 —
        채널을 갈라 곱하는 파티클 방식보다 1.75배 빠르다(실측 1.19ms →
        0.68ms, 348x498). 결과는 반올림 한 단계(±1)만 다르다.
        옛 Pillow 에 rawmode 가 없을 수 있으니 한 번 해 보고 물러난다.
        """
        if cls._FAST[0]:
            try:
                return im.convert("RGBa").tobytes("raw", "BGRa")
            except Exception:
                cls._FAST[0] = False
        return FxLayer._premul(im)

    def push(self, im, x, y):
        """그림을 화면 (x, y) 자리에 올린다. 자리·크기·그림을 한 번에.

        알파를 미리 곱해야 한다 (지뢰 117) — 안 곱하면 반투명 가장자리가
        밝아져 색 번짐 헤일로가 생긴다. 그림자가 무사했던 것은 새까매서
        (0×α=0) 티가 안 났을 뿐이다.
        """
        u, g = layer_api()
        if u is None:
            return False
        w, h = im.size
        if w <= 0 or h <= 0:
            return False
        if not self._shown:
            u.ShowWindow(self.hwnd, 4)           # SW_SHOWNOACTIVATE
            self._shown = True
        data = self._premul(im)
        hdc = u.GetDC(0)
        mem = g.CreateCompatibleDC(hdc)
        bmi = _BITMAPINFOHEADER()
        bmi.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
        bmi.biWidth, bmi.biHeight = w, -h        # 위에서 아래로
        bmi.biPlanes, bmi.biBitCount = 1, 32
        bits = ctypes.c_void_p()
        hbm = g.CreateDIBSection(hdc, ctypes.byref(bmi), 0,
                                 ctypes.byref(bits), None, 0)
        ctypes.memmove(bits, data, len(data))
        old = g.SelectObject(mem, hbm)
        blend = _BLENDFUNCTION(0, 0, 255, 1)     # AC_SRC_OVER, 알파 사용
        got = u.UpdateLayeredWindow(
            self.hwnd, hdc, ctypes.byref(_POINT(int(x), int(y))),
            ctypes.byref(_SIZE(w, h)), mem,
            ctypes.byref(_POINT(0, 0)), 0,
            ctypes.byref(blend), 2)              # ULW_ALPHA
        g.SelectObject(mem, old)
        g.DeleteObject(hbm)
        g.DeleteDC(mem)
        u.ReleaseDC(0, hdc)
        return bool(got)

    def place_above(self, owner_hwnd):
        """본체 창 바로 위 z순서로 올린다 (자리는 안 건드린다).

        **올리는 게 아니라 본체를 내린다.** 이 창을 맨 앞(HWND_TOP)으로
        올리면 그 위에 있어야 할 파티클 창까지 덮는다 — 대신 본체를 이
        창 뒤로 보내면 파티클과의 순서는 그대로 남는다.
        """
        u, _g = layer_api()
        if u is None or not owner_hwnd:
            return
        try:
            # 둘째 인자는 '이 창 뒤에 놓아라' 다 (지뢰 23)
            u.SetWindowPos(owner_hwnd, self.hwnd, 0, 0, 0, 0,
                           0x1 | 0x2 | 0x10)     # NOSIZE|NOMOVE|NOACTIVATE
        except Exception:
            pass

    def set_topmost(self, on):
        """'항상 위'를 캐릭터와 함께 움직인다 (그림자와 같은 이유)."""
        u, _g = layer_api()
        if u is None:
            return
        try:
            u.SetWindowPos(self.hwnd, -1 if on else -2, 0, 0, 0, 0,
                           0x1 | 0x2 | 0x10)
        except Exception:
            pass

    def hide(self):
        u, _g = layer_api()
        if self._shown and self.hwnd and u is not None:
            u.ShowWindow(self.hwnd, 0)
            self._shown = False

    def destroy(self):
        try:
            self.top.destroy()
        except Exception:
            pass
        self.hwnd = 0
        self.ok = False


class TeamStrip:
    """같이하는 친구들을 바탕화면에 두는 창 (요청 — 뽀모도로 창을 닫아도).

    윈도우는 레이어 창(진짜 알파 — 앉은 그림·말풍선·토마토·색종이의
    가장자리가 그대로 매끈)이고, 레이어를 못 쓰는 곳(맥)은 색상키 창으로
    물러난다. 그림은 마스코트가 PIL 한 장으로 합성해 넘긴다 — 이 클래스는
    창·입력·자리만 안다. 끌면 on_drag(dx, dy), 그냥 누르면 on_click(),
    우클릭이면 on_menu(), 끌기를 마치면 on_drop().
    """

    def __init__(self, root, key, on_click, on_drag, on_menu, on_drop=None,
                 on_hover=None):
        self.top = tk.Toplevel(root)
        self.top.overrideredirect(True)
        self.top.attributes("-topmost", True)
        self.key = key
        self.on_hover = on_hover
        self.hwnd = 0
        self.mode = "key"
        self._shown = False
        self._img = None
        self.canvas = None
        self.x = self.y = 0
        self.w = self.h = 1
        self.on_click, self.on_drag = on_click, on_drag
        self.on_menu, self.on_drop = on_menu, on_drop
        self._press = None
        self._moved = False
        self._premul = CharLayer._premul
        u = layer_api()[0] if IS_WIN else None
        if u is not None:
            try:
                self.top.update_idletasks()
                self.hwnd = int(self.top.wm_frame(), 16)
                ex = u.GetWindowLongW(self.hwnd, -20)
                # LAYERED | TOOLWINDOW | NOACTIVATE — TRANSPARENT 는 안 건다
                # (끌고 눌러야 한다 · 지뢰 118)
                u.SetWindowLongW(self.hwnd, -20,
                                 ex | 0x80000 | 0x80 | 0x8000000)
                self.mode = "layer"
                self._shown = True
                CharLayer.push(self, Image.new("RGBA", (1, 1), (0, 0, 0, 0)),
                               0, 0)
                self._shown = False
                u.ShowWindow(self.hwnd, 0)
            except Exception:
                self.mode = "key"
        if self.mode == "key":
            try:
                if IS_MAC:
                    self.top.attributes("-transparent", True)
                else:
                    self.top.attributes("-transparentcolor", key)
            except Exception:
                pass
            self.top.config(bg=key)
            self.canvas = tk.Canvas(self.top, width=1, height=1, bg=key,
                                    highlightthickness=0, bd=0)
            self.canvas.pack()
            self.top.withdraw()
            try:
                self.hwnd = int(self.top.wm_frame(), 16) if IS_WIN else 0
            except Exception:
                self.hwnd = 0
        for w9 in ((self.top, self.canvas) if self.canvas is not None
                   else (self.top,)):
            w9.bind("<Button-1>", self._on_press)
            w9.bind("<B1-Motion>", self._on_move)
            w9.bind("<ButtonRelease-1>", self._on_release)
            w9.bind("<Button-3>", self._on_menu)
            # 맥 Tk 는 우클릭이 <Button-2> 이고 Ctrl+클릭도 우클릭이다 —
            # <Button-3> 만 걸면 맥에서 판이 안 뜬다 (제보)
            w9.bind("<Button-2>", self._on_menu)
            w9.bind("<Control-Button-1>", self._on_menu)
            w9.bind("<Motion>", self._on_hover)
            w9.bind("<Leave>", lambda _e: self._on_hover(None))

    def _on_hover(self, e):
        if self.on_hover is None:
            return
        try:
            if e is None:
                self.on_hover(None, None)
            else:
                self.on_hover(e.x, e.y)
        except Exception:
            pass

    @property
    def visible(self):
        return bool(self._shown)

    def show(self, im, x, y):
        """그림을 화면 (x, y) 에 올린다 (레이어면 자리·그림 한 번에)."""
        self.x, self.y = int(x), int(y)
        self.w, self.h = im.size
        if self.mode == "layer":
            if not self._shown:
                u = layer_api()[0]
                if u is not None:
                    u.ShowWindow(self.hwnd, 4)       # SW_SHOWNOACTIVATE
                self._shown = True
            return CharLayer.push(self, im, self.x, self.y)
        try:
            key2 = tuple(int(str(self.key)[i:i + 2], 16) for i in (1, 3, 5))
            ph = ImageTk.PhotoImage(flat_on_key(im, key2))
            self.canvas.config(width=im.width, height=im.height)
            self.canvas.delete("all")
            self.canvas.create_image(0, 0, image=ph, anchor="nw")
            self._img = ph
            self.top.geometry("+%d+%d" % (self.x, self.y))
            if not self._shown:
                self.top.deiconify()
                self._shown = True
                # 맥 Tk 는 withdraw → deiconify 를 거치면 '항상 위'가
                # 풀린다 — 다시 못 박는다 (사가 제보: 클립스튜디오 뒤로 숨음)
                try:
                    self.top.attributes("-topmost", True)
                    self.top.lift()
                except Exception:
                    pass
            return True
        except Exception:
            return False

    def hide(self):
        if not self._shown:
            return
        self._shown = False
        try:
            if self.mode == "layer":
                u = layer_api()[0]
                if u is not None:
                    u.ShowWindow(self.hwnd, 0)
            else:
                self.top.withdraw()
        except Exception:
            pass

    def raise_top(self):
        """'항상 위' 창 사이에서 맨 앞으로 (HWND_TOP · 지뢰 23)."""
        if not self._shown:
            return
        try:
            if IS_WIN and self.hwnd:
                ctypes.windll.user32.SetWindowPos(
                    self.hwnd, 0, 0, 0, 0, 0, 0x1 | 0x2 | 0x10)
            else:
                # 맥 — 다른 앱(클립스튜디오) 창이 앞으로 오면 lift 만으로는
                # 못 이긴다. '항상 위'를 매번 다시 건다 (1초에 한 번).
                self.top.attributes("-topmost", True)
                self.top.lift()
        except Exception:
            pass

    def _on_press(self, e):
        # 맥의 Ctrl+클릭은 우클릭이다 — 그 누름·뗌을 왼쪽 클릭으로 세면
        # 메뉴가 뜨자마자 '창 열기'가 같이 돌았다 (사가 제보)
        if int(getattr(e, "state", 0) or 0) & 0x4:
            self._press = None
            self._moved = False
            return
        self._press = (e.x_root, e.y_root)
        self._moved = False

    def _on_move(self, e):
        if self._press is None:
            return
        dx, dy = e.x_root - self._press[0], e.y_root - self._press[1]
        if abs(dx) + abs(dy) < 2 and not self._moved:
            return
        self._moved = True
        self._press = (e.x_root, e.y_root)
        try:
            self.on_drag(dx, dy)
        except Exception:
            pass

    def _on_release(self, e):
        if self._press is None:
            return                     # Ctrl+클릭(메뉴)의 뗌 — 클릭이 아니다
        if int(getattr(e, "state", 0) or 0) & 0x4:
            self._press = None
            self._moved = False
            return
        moved = self._moved
        self._press = None
        self._moved = False
        try:
            if moved:
                if self.on_drop is not None:
                    self.on_drop()
            else:
                self.on_click()
        except Exception:
            pass

    def _on_menu(self, e):
        try:
            self.on_menu(e.x, e.y, e.x_root, e.y_root)
        except Exception:
            pass

    def destroy(self):
        try:
            self.top.destroy()
        except Exception:
            pass
        self.hwnd = 0
        self._shown = False


class MacCharLayer:
    """맥에서 캐릭터 몸을 진짜 반투명으로 올리는 층 (CALayer 덧레이어).

    윈도우는 별도 레이어 창(`CharLayer`)을 쓰지만 맥에는 그 API 가 없다.
    대신 **본체 창의 contentView 에 CALayer 를 하나 얹고** 거기에 우리가
    합성한 그림을 매 프레임 넣는다. 창을 새로 만들지 않으므로

      · 클릭·드래그가 지금 그대로다 (Tk 창이 계속 다 받는다)
      · 자리·크기·z순서를 따로 챙길 것이 없다
      · 부팅 경로를 안 건드린다

    는 이점이 있다. 덧레이어는 Tk 가 그린 것 **위**에 합성되므로, 캐릭터
    위에 얹는 것(모자·간식·말풍선)도 같은 그림에 들어가 있어야 한다 —
    시트가 draw() 끝까지 모으는 이유가 그것이다.

    맥에서 한 번도 돌려 보지 못한 길이라 **기본은 꺼 둔다.** 켜는 것은
    환경설정의 '부드러운 가장자리'이고, 어디서든 터지면 그 자리에서
    색상키 방식으로 되돌아간다.
    """

    def __init__(self, root):
        self.ok = False
        self.layer = None
        self._sz = None
        self._last_src = None    # 직전에 올린 프레임 (같으면 push 스킵)
        # **Quartz 가 있어야 한다.** 맥 번들에 pyobjc-framework-Quartz 가
        # 빠져 있으면 여기서 ImportError 로 깔끔하게 물러난다 — 부르는 쪽이
        # 색상키로 되돌린다.
        # 한때 'Quartz 없이도 되게' AppKit 의 NSBitmapImageRep 에 바이트를
        # 채우는 길을 붙였다가 **퀸시의 앱이 통째로 죽었다.** 파이썬 예외가
        # 아니라 프로세스가 사라지는 종류라 어떤 try 로도 못 잡는다.
        # 맥에서 못 돌려 보는 코드에 그런 길을 붙이면 안 된다 (지뢰 130).
        from Quartz import CALayer
        root.update_idletasks()
        # Tk 창 → NSView → 그 레이어. PyObjC 로만 다룬다 (ctypes 로 직접
        # 포인터를 만지면 잘못됐을 때 그 자리서 프로세스가 죽는다).
        from AppKit import NSApp
        view = None
        for w in NSApp.windows():
            try:
                sz = w.frame().size
                if (abs(sz.width - root.winfo_width()) <= 2
                        and abs(sz.height - root.winfo_height()) <= 2):
                    view = w.contentView()
                    break
            except Exception:
                pass
        if view is None:
            raise RuntimeError("본체 창을 못 찾음")
        view.setWantsLayer_(True)
        host = view.layer()
        if host is None:
            raise RuntimeError("레이어가 없음")
        # **레티나 배율을 맞춘다.** CALayer 는 기본이 1배라, 2배 화면에서
        # 우리 그림이 그대로 늘어나 가장자리가 뭉개진다 (제보 '픽셀이
        # 깨진 듯'). 창의 backingScaleFactor 를 넣고, 그림도 그 배율로
        # 만들어 넣는다.
        self.scale = 1.0
        try:
            sc = float(view.window().backingScaleFactor())
            if 1.0 <= sc <= 4.0:
                self.scale = sc
        except Exception:
            pass
        # 진단용 — 맥에서 처음 도는 길이라, 어긋났을 때 이 값들로 한 번에
        # 갈린다. 뷰가 뒤집혀 있는지(그림이 거꾸로 나오는지)가 특히 중요하다.
        self.diag = ""
        try:
            b0 = view.bounds()
            self.diag = ("배율 %.2f · 뷰 %.0fx%.0f · flipped=%s"
                         % (self.scale, b0.size.width, b0.size.height,
                            bool(view.isFlipped())))
        except Exception:
            pass
        lay = CALayer.layer()
        # **contentsScale 은 1로 둔다.** 배율(레티나)만큼 그림을 CPU 로
        # 키워 넣던 예전 방식은 매 프레임 LANCZOS 리사이즈가 돌아
        # (실측 728x998 → 2배 36ms + 변환 12ms) 아바타를 키운 맥에서
        # 앱이 먹통이 됐다 (사가·퀸시 렉 제보). 1배 그림을 넣고 확대는
        # GPU(레이어 합성)가 한다 — 기본 보간이 linear 라 부드럽고,
        # 색상키 시절과 같은 선명도다.
        lay.setContentsScale_(1.0)
        lay.setContentsGravity_("topLeft")
        # 애니메이션을 끄지 않으면 그림을 바꿀 때마다 페이드가 걸려
        # 잔상이 남고 프레임이 밀린다.
        lay.setActions_({"contents": None, "position": None, "bounds": None})
        host.addSublayer_(lay)
        self.view, self.host, self.layer = view, host, lay
        self.ok = True

    def push(self, im, _x=None, _y=None):
        """합성한 그림을 덧레이어에 올린다 (알파는 미리 곱한다 — 지뢰 117).

        레티나면 그 배율로 키워서 넣는다 — contentsScale 만 올리고 그림은
        1배로 두면 반대로 절반 크기로 나온다.
        """
        # 레티나 리사이즈는 GPU 가 한다 (contentsScale=1 — __init__ 참고).
        from Foundation import NSData
        from Quartz import (CATransaction, CGColorSpaceCreateDeviceRGB,
                            CGDataProviderCreateWithCFData, CGImageCreate,
                            kCGImageAlphaPremultipliedLast)
        # 안 바뀐 프레임은 통째로 건너뛴다 (퀸시 맥 실측 — 캐릭터가 멈춰
        # 있을 때 push 가 그대로 프레임 비용이었다). 비교(700KB memcmp)는
        # 변환+CGImage 만들기보다 훨씬 싸다.
        src = im.tobytes()
        if src == getattr(self, "_last_src", None):
            return True
        self._last_src = src
        w, h = im.size
        raw = im.convert("RGBa").tobytes("raw", "RGBa")
        data = NSData.dataWithBytes_length_(raw, len(raw))
        prov = CGDataProviderCreateWithCFData(data)
        img = CGImageCreate(w, h, 8, 32, w * 4,
                            CGColorSpaceCreateDeviceRGB(),
                            kCGImageAlphaPremultipliedLast, prov, None,
                            False, 0)
        if img is None:
            raise RuntimeError("CGImage 못 만듦")
        CATransaction.begin()
        CATransaction.setDisableActions_(True)
        try:
            b = self.view.bounds()
            if self._sz != (b.size.width, b.size.height):
                self._sz = (b.size.width, b.size.height)
                self.layer.setFrame_(b)
            self.layer.setContents_(img)
        finally:
            CATransaction.commit()
        return True

    def hide(self):
        self._last_src = None      # 다음 push 는 반드시 그린다 (스킵 무효화)
        try:
            from Quartz import CATransaction
            CATransaction.begin()
            CATransaction.setDisableActions_(True)
            self.layer.setContents_(None)
            CATransaction.commit()
        except Exception:
            pass

    # 윈도우 CharLayer 와 같은 이름의 z순서 메서드 — 맥은 덧레이어라
    # 본체 창과 z순서를 다툴 일이 없다. **없으면 tick 이 8초마다
    # AttributeError 로 죽는다** (CI 맥 러너가 잡아낸 실사고 — z순서
    # 재고정·창 이동·상태 칩 핀이 전부 이 이름을 부른다).
    def place_above(self, owner_hwnd):
        pass

    def set_topmost(self, on):
        pass

    def destroy(self):
        try:
            self.layer.removeFromSuperlayer()
        except Exception:
            pass
        self.layer = None
        self.ok = False


class _CharSheet:
    """캐릭터를 PIL 그림 한 장에 모으는, 캔버스인 척하는 물건 (매끈 경로).

    몸을 그리는 동안만 `self.canvas` 자리에 들어앉는다. 캐릭터 구역이 쓰는
    그리기(그림·선·타원·사각형·다각형)만 받아 PIL 에 그리고, **모르는 것은
    진짜 캔버스로 넘긴다** — 그러면 옛 코드가 그대로 돌고, 넘어간 것은
    레이어보다 위에 그려진다(본체 창이 위이므로). 안 보이는 것보다 낫다.
    """

    def __init__(self, real, w, h, owner=None):
        self.real = real
        self.owner = owner        # Mascot — 글꼴·배율을 물어볼 곳
        self.im = Image.new("RGBA", (max(1, int(w)), max(1, int(h))),
                            (0, 0, 0, 0))
        self.spill = 0            # 진짜 캔버스로 넘어간 횟수 (검사용)
        self._dr = None

    def __getattr__(self, name):
        # 조회(bbox·coords·winfo_*)는 진짜 캔버스가 답한다. `real` 이
        # 아직 없을 때 무한 재귀가 나지 않게 __dict__ 로 직접 본다.
        real = self.__dict__.get("real")
        if real is None:
            raise AttributeError(name)
        return getattr(real, name)

    @property
    def dr(self):
        if self._dr is None:
            self._dr = ImageDraw.Draw(self.im)
        return self._dr

    # ── 색·좌표 다듬기 ────────────────────────────────────────────────
    @staticmethod
    def _col(v):
        """Tk 색 문자열 → PIL 색. 빈 값은 '안 칠함'."""
        if not v or v in ("", "none"):
            return None
        return v

    @staticmethod
    def _flat(a):
        """create_line(x0,y0,x1,y1) 과 create_line([(x,y),…]) 둘 다 받는다."""
        if len(a) == 1 and isinstance(a[0], (list, tuple)):
            a = a[0]
        out = []
        for v in a:
            if isinstance(v, (list, tuple)):
                out.extend(float(x) for x in v)
            else:
                out.append(float(v))
        return [(out[i], out[i + 1]) for i in range(0, len(out) - 1, 2)]

    @staticmethod
    def _spline(pts, steps=12, closed=False):
        """Tk 의 smooth=True 와 같은 2차 스플라인.

        Tk 는 꼭짓점을 조종점으로, 변의 중점을 지나는 곡선을 그린다. PIL 에는
        대응이 없어 직접 푼다 — 안 풀면 슬라임과 낙서가 각진 다각형이 된다.
        """
        n = len(pts)
        if n < 3:
            return list(pts)
        steps = max(2, min(24, int(steps or 12)))

        def mid(a, b):
            return ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0)

        def quad(p0, p1, p2, out):
            for i in range(1, steps + 1):
                t = i / float(steps)
                u = 1.0 - t
                out.append((u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0],
                            u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]))

        out = []
        if closed:
            out.append(mid(pts[-1], pts[0]))
            for i in range(n):
                quad(mid(pts[i - 1], pts[i]), pts[i],
                     mid(pts[i], pts[(i + 1) % n]), out)
        else:
            out.append(pts[0])
            for i in range(1, n - 1):
                p0 = pts[0] if i == 1 else mid(pts[i - 1], pts[i])
                p2 = pts[-1] if i == n - 2 else mid(pts[i], pts[i + 1])
                quad(p0, pts[i], p2, out)
            out.append(pts[-1])
        return out

    # ── 캔버스 흉내 ───────────────────────────────────────────────────
    def delete(self, *_a):
        return None                # 시트는 프레임마다 새로 만든다

    def blit(self, pil, x, y, anchor="nw"):
        w, h = pil.size
        a = str(anchor or "nw")
        if a == "center":
            x, y = x - w / 2.0, y - h / 2.0
        else:
            if "e" in a:
                x -= w
            elif "w" not in a:
                x -= w / 2.0
            if "s" in a:
                y -= h
            elif "n" not in a:
                y -= h / 2.0
        self.im.alpha_composite(pil, (int(round(x)), int(round(y))))

    def create_image(self, x, y, image=None, anchor="nw", **_kw):
        pil = image if isinstance(image, Image.Image) else \
            getattr(image, "_pil_src", None)
        if pil is None:
            # 무엇인지 모르는 그림 — 안 보이는 것보다 캔버스에 그리는 게 낫다
            self.spill += 1
            return self.real.create_image(x, y, image=image, anchor=anchor,
                                          **_kw)
        self.blit(pil, x, y, anchor)
        return 0

    def create_rectangle(self, x0, y0, x1, y1, fill="", outline="", width=1,
                         **_kw):
        f, o = self._col(fill), self._col(outline)
        if f is None and o is None:
            return 0
        self.dr.rectangle([min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)],
                          fill=f, outline=o, width=max(1, int(width or 1)))
        return 0

    def create_oval(self, x0, y0, x1, y1, fill="", outline="", width=1, **_kw):
        f, o = self._col(fill), self._col(outline)
        if f is None and o is None:
            return 0
        self.dr.ellipse([min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)],
                        fill=f, outline=o, width=max(1, int(width or 1)))
        return 0

    def create_line(self, *a, **kw):
        pts = self._flat(a)
        if len(pts) < 2:
            return 0
        if kw.get("smooth"):
            pts = self._spline(pts, kw.get("splinesteps", 12))
        col = self._col(kw.get("fill", "#000000")) or "#000000"
        w = max(1, int(round(float(kw.get("width", 1) or 1))))
        self.dr.line(pts, fill=col, width=w,
                     joint="curve" if w > 2 else None)
        if w > 2 and str(kw.get("capstyle", "")) == "round":
            r = w / 2.0
            for px, py in (pts[0], pts[-1]):
                self.dr.ellipse([px - r, py - r, px + r, py + r], fill=col)
        return 0

    def bbox(self, *a):
        """시트가 만든 항목(0)은 잴 수 없다 — None 을 준다.

        진짜 캔버스로 0 을 넘기면 TclError 가 나고, 그 구역이 _safe 에
        세 번 걸려 꺼진다 (지뢰 14).
        """
        if a and not a[0]:
            return None
        try:
            return self.real.bbox(*a)
        except Exception:
            return None

    def create_text(self, x, y, **kw):
        """글자 — Tk 글꼴(포인트)을 PIL 픽셀로 바꿔 그린다 (지뢰 93).

        Tk 는 포인트, PIL 은 픽셀이라 `tk scaling` 을 곱해야 크기가 같다.
        굵기는 글꼴 튜플의 셋째 값으로 가른다. 못 그리면 진짜 캔버스로
        넘긴다 — 자리는 맞고 층만 달라진다(안 보이는 것보다 낫다).
        """
        txt = str(kw.get("text", ""))
        own = self.owner
        if not txt or own is None:
            return 0 if not txt else self._spill_text(x, y, **kw)
        try:
            f = kw.get("font") or ()
            pt = 10.0
            bold = False
            if isinstance(f, (tuple, list)):
                if len(f) > 1:
                    pt = abs(float(f[1]))
                bold = any(str(v).lower() == "bold" for v in f[2:])
            px = max(6, int(round(pt * own._tk_ppp())))
            font = own._pil_font(px, bold)
            if font is None:
                return self._spill_text(x, y, **kw)
            d = self.dr
            anc = str(kw.get("anchor", "center")).strip().lower()
            # PIL 의 기준점 이름이 Tk 와 다르다 — 옮겨 준다.
            # **'center' 를 먼저 걸러야 한다** — 그 글자 안에 'e' 가 들어
            # 있어서 나침반 글자로 훑으면 오른쪽 정렬로 잡힌다 (실제로
            # 말풍선 글자가 왼쪽으로 밀렸다).
            if anc in ("", "c", "center"):
                ax, ay = "m", "m"
            else:
                ax = "l" if "w" in anc else ("r" if "e" in anc else "m")
                ay = "a" if "n" in anc else ("d" if "s" in anc else "m")
            fill = self._col(kw.get("fill", "#000000")) or "#000000"
            lines = txt.split("\n")
            if len(lines) == 1:
                d.text((x, y), txt, font=font, fill=fill, anchor=ax + ay)
                return 0
            lh = px * 1.25
            y0 = y - (len(lines) - 1) * lh / 2.0 if ay == "m" else y
            just = str(kw.get("justify", "center"))
            for i, ln in enumerate(lines):
                d.text((x, y0 + i * lh), ln, font=font, fill=fill,
                       anchor=("m" if just == "center" else ax) + "m")
            return 0
        except Exception:
            return self._spill_text(x, y, **kw)

    def _spill_text(self, x, y, **kw):
        self.spill += 1
        return self.real.create_text(x, y, **kw)

    def create_arc(self, x0, y0, x1, y1, **kw):
        """호 — 파이/현/호 세 가지 모양을 PIL 로."""
        try:
            st = float(kw.get("start", 0.0))
            ext = float(kw.get("extent", 90.0))
        except Exception:
            return 0
        # Tk 는 반시계, PIL 은 시계 방향이라 부호를 뒤집는다
        a0, a1 = -(st + ext), -st
        box = [min(x0, x1), min(y0, y1), max(x0, x1), max(y0, y1)]
        f = self._col(kw.get("fill", ""))
        o = self._col(kw.get("outline", ""))
        w = max(1, int(round(float(kw.get("width", 1) or 1))))
        style = str(kw.get("style", "pieslice"))
        try:
            if style == "arc":
                self.dr.arc(box, a0, a1, fill=o or f or "#000000", width=w)
            elif style == "chord":
                self.dr.chord(box, a0, a1, fill=f, outline=o, width=w)
            else:
                self.dr.pieslice(box, a0, a1, fill=f, outline=o, width=w)
        except Exception:
            self.spill += 1
            return self.real.create_arc(x0, y0, x1, y1, **kw)
        return 0

    def create_polygon(self, *a, **kw):
        pts = self._flat(a)
        if len(pts) < 3:
            return 0
        if kw.get("smooth"):
            pts = self._spline(pts, kw.get("splinesteps", 12), closed=True)
        f = self._col(kw.get("fill", ""))
        o = self._col(kw.get("outline", ""))
        w = max(1, int(round(float(kw.get("width", 1) or 1))))
        if f is not None:
            self.dr.polygon(pts, fill=f)
        if o is not None:
            self.dr.line(list(pts) + [pts[0]], fill=o, width=w,
                         joint="curve" if w > 2 else None)
        return 0


def _off_line(p, q, toward, dist):
    """선분 p→q 를 `toward` 쪽으로 dist 만큼 민 직선 (두 점으로)."""
    dx, dy = q[0] - p[0], q[1] - p[1]
    n = math.hypot(dx, dy) or 1.0
    nx, ny = -dy / n, dx / n
    if (toward[0] - p[0]) * nx + (toward[1] - p[1]) * ny < 0:
        nx, ny = -nx, -ny
    return ((p[0] + nx * dist, p[1] + ny * dist),
            (q[0] + nx * dist, q[1] + ny * dist))


def _cross_pt(l1, l2):
    """두 직선의 교점. 거의 평행이면 None."""
    (x1, y1), (x2, y2) = l1
    (x3, y3), (x4, y4) = l2
    den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
    if abs(den) < 1e-6:
        return None
    a = x1 * y2 - y1 * x2
    b = x3 * y4 - y3 * x4
    return ((a * (x3 - x4) - (x1 - x2) * b) / den,
            (a * (y3 - y4) - (y1 - y2) * b) / den)


def _line_at_y(l, y):
    """직선 위에서 그 높이의 점."""
    (x1, y1), (x2, y2) = l
    if abs(y2 - y1) < 1e-6:
        return (x1, y)
    return (x1 + (x2 - x1) * (y - y1) / (y2 - y1), y)


def bubble_img(w, h, r, tail, fill, outline, lw, S=4, pad=0):
    """말풍선 한 장 (RGBA, 알파 그대로 — 가장자리가 반투명이다).

    **몸통과 꼬리를 하나의 실루엣으로 그린다.** 바깥을 테두리색으로 채우고
    그 안쪽을 채움색으로 덮는 방식이다. 선을 따로 긋던 예전 방식은 셋을
    한꺼번에 못 줬다 — 이음매에 가로선이 남고(제보), 몸통과 꼬리의 테두리가
    뚝 끊겨 보이고, 꼬리 끝이 뭉툭했다. 실루엣으로 그리면 셋 다 저절로
    풀리고 끝도 뾰족하게 모인다.

    tail — (밑변 왼쪽 x, 밑변 오른쪽 x, 끝점 x, 꼬리 높이) 또는 None.
    셋 다 몸통 왼쪽 위 모서리 기준이고, 끝점은 몸통 아랫변에서 그만큼 아래다.
    w·h·r·lw 은 1배 기준이고, 안에서 S배로 그린 뒤 줄인다.
    """
    th = tail[3] if tail else 0
    W2, H2 = int(w + pad * 2 + 2), int(h + th + pad * 2 + 2)
    im = Image.new("RGBA", (W2 * S, H2 * S), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    lw = max(1.0, float(lw)) * S
    o = pad * S
    x0, y0, x1, y1 = o, o, o + w * S - 1, o + h * S - 1

    tri = None
    if tail:
        ta, tb, tt, _th = tail
        tri = ((o + ta * S, y1), (o + tt * S, y1 + th * S), (o + tb * S, y1))

    # 바깥 실루엣 — 테두리 색
    d.rounded_rectangle([x0, y0, x1, y1], radius=r * S, fill=outline or fill)
    if tri:
        d.polygon(list(tri), fill=outline or fill)
    # 안쪽 실루엣 — 채움색 (테두리 굵기만큼 안으로)
    d.rounded_rectangle([x0 + lw, y0 + lw, x1 - lw, y1 - lw],
                        radius=max(0.0, r * S - lw), fill=fill)
    if tri:
        a, tp, b = tri
        l1 = _off_line(a, tp, b, lw)
        l2 = _off_line(tp, b, a, lw)
        t2 = _cross_pt(l1, l2)
        if t2 is not None:
            # 몸통 속까지 끌어올려 안쪽끼리 이어 붙인다 (틈이 안 생기게)
            yy = y1 - lw * 2
            d.polygon([_line_at_y(l1, yy), t2, _line_at_y(l2, yy)], fill=fill)
    return im.resize((W2, H2), Image.LANCZOS)


def flat_on_key(im, key_rgb, floor=140, cut=40):
    """색상키 창에 얹을 수 있게 반투명 가장자리를 키 색과 미리 섞는다.

    색상키 투명창은 반투명을 못 담는다. 그대로 두면 키 색(거의 검정)과
    섞여 흰 바탕에서 어두운 얼룩 테가 진다 — 섞는 비율에 하한(55%)을 둬
    중간톤으로 만든다 (지뢰 65).
    """
    a = im.split()[3]
    a3 = a.point(lambda v: floor + v * (255 - floor) // 255 if v >= cut else 0)
    rgb = Image.composite(im.convert("RGB"),
                          Image.new("RGB", im.size, tuple(key_rgb)), a3)
    a2 = a.point(lambda v: 255 if v >= cut else 0)
    return Image.merge("RGBA", (*rgb.split(), a2))


class _WAVEFORMATEX(ctypes.Structure):
    _fields_ = [("wFormatTag", ctypes.c_uint16), ("nChannels", ctypes.c_uint16),
                ("nSamplesPerSec", ctypes.c_uint32), ("nAvgBytesPerSec", ctypes.c_uint32),
                ("nBlockAlign", ctypes.c_uint16), ("wBitsPerSample", ctypes.c_uint16),
                ("cbSize", ctypes.c_uint16)]


class _WAVEHDR(ctypes.Structure):
    _fields_ = [("lpData", ctypes.c_void_p), ("dwBufferLength", ctypes.c_uint32),
                ("dwBytesRecorded", ctypes.c_uint32), ("dwUser", ctypes.c_void_p),
                ("dwFlags", ctypes.c_uint32), ("dwLoops", ctypes.c_uint32),
                ("lpNext", ctypes.c_void_p), ("reserved", ctypes.c_void_p)]


# 샘플 폭(바이트)별 정수 타입 — 볼륨을 샘플에 곱할 때 사용
_SAMPLE_CTYPE = {1: ctypes.c_int8, 2: ctypes.c_int16, 4: ctypes.c_int32}


def _scaled_buffer(data, gain, sampwidth):
    """PCM 바이트에 gain을 곱한 재생 버퍼. 비트 심도(16/32bit)에 맞춰 스케일.

    waveOutSetVolume이 드라이버에 무시될 수 있어 샘플 값 자체를 조절한다.
    """
    buf = ctypes.create_string_buffer(data, len(data))
    ct = _SAMPLE_CTYPE.get(sampwidth)
    if gain < 0.999 and ct is not None and len(data) >= sampwidth:
        n = len(data) // sampwidth
        arr = (ct * n).from_buffer(buf)
        for i in range(n):
            arr[i] = int(arr[i] * gain)
    return buf


class SoundPack:
    """Mechvibes 사운드 팩(multi 타입: 키별 wav) 재생기.

    winmm waveOut API 직접 호출 — 외부 라이브러리 불필요, 어느 스레드에서든
    안전(메시지 펌프 불요), 재생마다 독립 장치라 동시 재생 가능.
    (MCI는 연 스레드에 묶여 리스너 스레드에서 멈추는 문제가 있어 사용 안 함)
    """

    def __init__(self, folder, volume=60):
        import threading
        import wave
        with open(os.path.join(folder, "config.json"), encoding="utf-8") as fp:
            cfg = json.load(fp)
        if cfg.get("key_define_type", "multi") != "multi":
            raise ValueError("single 타입 팩 미지원 — wav 분할형 팩을 사용하세요")
        names = []
        for v in cfg.get("defines", {}).values():
            if isinstance(v, str) and v and v not in names:
                names.append(v)
        self.raw = []             # (WAVEFORMATEX, 원본PCM, 샘플폭)
        slot = {}                 # 파일 이름 -> raw 안에서의 번호
        for name in names:
            path = os.path.join(folder, name)
            if not (name.lower().endswith(".wav") and os.path.exists(path)):
                continue
            with wave.open(path, "rb") as w:
                ch, sw, fr = w.getnchannels(), w.getsampwidth(), w.getframerate()
                data = w.readframes(w.getnframes())
            wfx = _WAVEFORMATEX(1, ch, fr, fr * ch * sw, ch * sw, sw * 8, 0)
            slot[name] = len(self.raw)
            self.raw.append((wfx, data, sw))
        if not self.raw:
            raise ValueError("재생 가능한 wav가 없음")
        # 팩은 스캔코드마다 쓸 음원을 config.json에 적어 둔다. 스페이스·백스페이스
        # 처럼 소리가 다른 키를 위한 것인데, 지금까지는 이 표를 버리고 아무 음원이나
        # 골라 썼다 (스페이스 소리가 엉뚱한 글자 키에서 났다).
        self.by_code = {}
        for code, fname in (cfg.get("defines") or {}).items():
            i = slot.get(fname)
            if i is not None:
                self.by_code[str(code)] = i
        self._active = []         # (핸들, WAVEHDR) — 재생 끝나면 정리
        self._lock = threading.Lock()
        self.set_volume(volume)

    def set_volume(self, volume):
        """볼륨(0~100)을 샘플에 곱해 재생용 버퍼 준비 (드라이버 볼륨 무시 대비)."""
        self.volume = max(0.0, min(float(volume), 100.0))
        gain = self.volume / 100.0
        self.sounds = []          # (WAVEFORMATEX, 버퍼, 길이)
        if gain <= 0.0:
            return
        for wfx, data, sw in self.raw:
            self.sounds.append((wfx, _scaled_buffer(data, gain, sw), len(data)))

    def play(self, key, code=None):
        if not self.sounds:
            return
        i = self.by_code.get(str(code)) if code is not None else None
        if i is None or i >= len(self.sounds):
            i = hash(str(key)) % len(self.sounds)   # 표에 없는 키는 아무거나
        wfx, buf, ln = self.sounds[i]
        wm = ctypes.windll.winmm
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF, ctypes.byref(wfx), 0, 0, 0):
            return
        wm.waveOutSetVolume(h, 0xFFFFFFFF)   # 앱/장치 볼륨 고정 해제 (실볼륨은 샘플로)
        hdr = _WAVEHDR()
        hdr.lpData = ctypes.cast(buf, ctypes.c_void_p)
        hdr.dwBufferLength = ln
        wm.waveOutPrepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        with self._lock:
            self._active.append((h, hdr))
            self._reap_locked(limit=24)

    def reap(self):
        """재생이 끝난 장치 정리 (주기 호출용)."""
        with self._lock:
            self._reap_locked(limit=24)

    def _reap_locked(self, limit):
        wm = ctypes.windll.winmm
        keep = []
        for h, hdr in self._active:
            if hdr.dwFlags & 0x1:     # WHDR_DONE
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr),
                                          ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            else:
                keep.append((h, hdr))
        while len(keep) > limit:      # 안전판: 과도한 동시 재생 방지
            h, hdr = keep.pop(0)
            wm.waveOutReset(h)
            wm.waveOutUnprepareHeader(h, ctypes.byref(hdr),
                                      ctypes.sizeof(_WAVEHDR))
            wm.waveOutClose(h)
        self._active = keep

    def close(self):
        with self._lock:
            wm = ctypes.windll.winmm
            for h, hdr in self._active:
                wm.waveOutReset(h)
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr),
                                          ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            self._active = []


class PenSound:
    """선을 긋기 시작할 때 스크리블 클립 하나를 랜덤 재생 (한 번 '슥').

    짧은 선이든 긴 선이든 스트로크마다 클립 하나. 지속음(bed) 없음.
    볼륨은 waveOutSetVolume이 드라이버에 무시될 수 있어(장치별 볼륨 미지원)
    샘플 값 자체에 곱해 확실히 적용한다. 0이면 아예 재생하지 않는다.
    """

    def __init__(self, folder, volume=35):
        import wave
        self.raw = []             # (WAVEFORMATEX, 원본PCM, 샘플폭)
        names = [f for f in sorted(os.listdir(folder)) if f.lower().endswith(".wav")]
        clips = [f for f in names if f.lower().startswith("clip")] or names
        for f in clips:
            with wave.open(os.path.join(folder, f), "rb") as w:
                ch, sw, fr = w.getnchannels(), w.getsampwidth(), w.getframerate()
                data = w.readframes(w.getnframes())
            wfx = _WAVEFORMATEX(1, ch, fr, fr * ch * sw, ch * sw, sw * 8, 0)
            self.raw.append((wfx, data, sw))
        if not self.raw:
            raise ValueError("펜 소리 wav 없음")
        self.set_volume(volume)
        self._cur = None          # (핸들, WAVEHDR, 버퍼)

    def set_volume(self, volume):
        """볼륨(0~100)을 샘플에 곱해 재생용 버퍼를 준비."""
        self.volume = max(0.0, min(float(volume), 100.0))
        gain = self.volume / 100.0
        self.clips = []           # (WAVEFORMATEX, 버퍼, 길이)
        if gain <= 0.0:
            return                # 무음이면 버퍼 안 만듦 → play()가 그냥 반환
        for wfx, data, sw in self.raw:
            self.clips.append((wfx, _scaled_buffer(data, gain, sw), len(data)))

    def play(self):
        """랜덤 클립 하나 재생 (선 긋기 시작 시). 볼륨 0이면 무음."""
        if not self.clips:
            return
        wm = ctypes.windll.winmm
        if self._cur is not None:
            self._release(self._cur)
            self._cur = None
        wfx, buf, ln = random.choice(self.clips)
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF, ctypes.byref(wfx), 0, 0, 0):
            return
        wm.waveOutSetVolume(h, 0xFFFFFFFF)   # 앱/장치 볼륨 고정 해제 (실볼륨은 샘플로)
        hdr = _WAVEHDR()
        hdr.lpData = ctypes.cast(buf, ctypes.c_void_p)
        hdr.dwBufferLength = ln
        wm.waveOutPrepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        self._cur = (h, hdr, buf)

    def stop(self):
        if self._cur is not None:
            self._release(self._cur)
            self._cur = None

    @staticmethod
    def _release(dev):
        wm = ctypes.windll.winmm
        h, hdr, _buf = dev
        wm.waveOutReset(h)
        wm.waveOutUnprepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        wm.waveOutClose(h)


class PenGrainSound:
    """펜 긋는 소리 — 지속 재생(연속 스크레이프) 방식.

    긴 스크레이프 녹음(sustain.wav)이 있으면 그중 가장 고른 구간을 골라
    이음매 없이 무한 반복한다(실제 연필 질감 그대로). 없으면 짧은 클립들을
    진폭 평탄화해 만든 베드로 폴백한다.
      · 짧은 획은 짧게, 긴 획은 길게 — 소리 길이가 손을 그대로 따라간다.
      · 한 획이 '스으으윽' 하나로 이어진다(루프가 매끄러워 회전음 없음).
      · 획마다 피치만 살짝 달리해 반복감을 줄이고, 시작 볼륨에 속도를 싣는다.

    **페이드는 전부 샘플에 미리 구워 둔다.** 재생 중 waveOutSetVolume으로
    줄이면 드라이버에 따라 볼륨이 핸들별이 아니라 전역으로 먹어서, 직전 획의
    페이드아웃이 방금 시작한 다음 획까지 끌어내린다(빠른 연타에서 소리가
    10%대로 씹히던 원인). 그래서 짧은 클립은 꼬리를 구워 두고 발사 후엔
    손대지 않고, 루프는 페이드인 머리·페이드아웃 꼬리 버퍼를 따로 재생한다.
    """

    BED_S = 1.5            # 베드 최대 길이(초) — 길수록 반복 주기가 길어짐
    XFADE_S = 0.04         # 이음매 크로스페이드(초)
    HEAD_S = 0.12          # 루프 페이드인 머리(초) — 짧은 클립 밑에서 올라옴
    TAIL_S = 0.13          # 루프 페이드아웃 꼬리(초)
    SHORT_CAP = 0.26       # 짧은 클립 최대 길이(초) — 획보다 길게 남지 않게
    SHORT_MAX = 0.16       # 이 시간 넘게 이어지면 루프로 전환(짧은 클립과 겹침)
    MOVE_MIN = 4.0         # 획 시작 판정(px) — 마우스 이벤트로 재므로 낮게 잡는다

    def __init__(self, folder, volume=30):
        import wave
        names = [f for f in sorted(os.listdir(folder)) if f.lower().endswith(".wav")]
        longs = [f for f in names if "sustain" in f.lower() or "long" in f.lower()]
        self.fr = 44100

        def read(fname):
            with wave.open(os.path.join(folder, fname), "rb") as w:
                if w.getsampwidth() != 2 or w.getnchannels() != 1:
                    raise ValueError("펜 소리는 16bit 모노 wav만 지원")
                self.fr = w.getframerate()
                return list(memoryview(bytearray(w.readframes(w.getnframes()))).cast("h"))

        if longs:                                     # 실제 긴 스크레이프 → 그대로 루프
            flat = self._steady_bed(read(longs[0]))
        else:                                         # 짧은 클립 → 평탄화 베드(폴백)
            pcm = []
            for f in ([c for c in names if c.lower().startswith("clip")] or names):
                pcm += read(f)
            flat = self._voiced_flat(pcm)
        m = len(flat)
        X = max(4, int(self.fr * self.XFADE_S))
        Lb = min(m - X, int(self.fr * self.BED_S))
        if Lb < 8:
            raise ValueError("펜 소리가 너무 짧아 베드를 못 만듦")
        # 크로스페이드 루프: loop[Lb-1] → loop[0] 이 매끄럽게 맞물리게
        loop = (ctypes.c_int16 * Lb)()
        for i in range(Lb):
            if i < X:
                w = i / X
                loop[i] = int(flat[i] * w + flat[Lb + i] * (1.0 - w))
            else:
                loop[i] = flat[i]
        self.loop_pcm = bytes(loop)
        # 루프 머리(페이드인)·꼬리(페이드아웃) — 볼륨 API 대신 이걸 재생한다.
        H = min(Lb, max(8, int(self.fr * self.HEAD_S)))
        head = (ctypes.c_int16 * H)()
        for i in range(H):
            head[i] = int(loop[i] * (i / H))
        self._head_pcm = bytes(head)
        T = min(Lb, max(8, int(self.fr * self.TAIL_S)))
        rise = max(2, int(self.fr * 0.003))       # 이음매 클릭 방지용 3ms 상승
        tail = (ctypes.c_int16 * T)()
        for i in range(T):
            g = (1.0 - i / T) * (min(i, rise) / rise)
            tail[i] = int(loop[i] * g)
        self._tail_pcm = bytes(tail)
        # 짧은 획용: clip_*.wav 를 원샷 재생. 길이를 SHORT_CAP으로 자르고 끝에
        # 페이드 꼬리를 구워 둔다 — 재생 뒤엔 손대지 않아도 획 길이에 맞는다.
        self.shorts = []
        for f in [c for c in names if c.lower().startswith("clip")]:
            with wave.open(os.path.join(folder, f), "rb") as w:
                if w.getsampwidth() != 2 or w.getnchannels() != 1:
                    continue
                s = list(memoryview(bytearray(
                    w.readframes(w.getnframes()))).cast("h"))
            cap = int(self.fr * self.SHORT_CAP)
            if len(s) > cap:
                s = s[:cap]
            fo = max(4, int(self.fr * 0.05))      # 끝 50ms 페이드아웃
            if len(s) > fo:
                for i in range(fo):
                    s[len(s) - fo + i] = int(s[len(s) - fo + i] * (1.0 - i / fo))
            arr = (ctypes.c_int16 * len(s))(*s)
            self.shorts.append(bytes(arr))
        self.shorts.sort(key=len)
        # 마우스 콜백(후킹 스레드)과 그리기 루프(메인)가 같이 보는 것들을 지킨다
        self._lock = threading.Lock()
        self._short_bufs = []            # [클립][볼륨단계] 미리 구운 재생 버퍼
        self._tail_bufs = {}             # 볼륨별 루프 꼬리 버퍼
        self.set_volume(volume)
        self._voice = None               # 루프 재생 (handle, WAVEHDR, buf)
        self._playing = False            # 루프 재생 중인가
        self._down = False               # 펜이 눌려 있는가 (마우스 콜백이 갱신)
        self._stroke_dist = 0.0          # 이번 획에서 누적 이동(px)
        self._stroke_fired = False       # 이번 획에서 짧은 소리를 냈는가
        self._stroke_t = 0.0             # 짧은 소리를 낸 시각(루프 전환 기준)
        self._moving_t = 0.0             # 마지막으로 실제 움직인 시각
        self._cur_speed = 0.0            # 최근 이동 속도(클립 선택·볼륨용)
        self._last_xy = None             # 직전 마우스 이벤트 좌표
        self._last_ev = 0.0              # 직전 마우스 이벤트 시각
        self._last_pick = -1             # 직전에 고른 클립 (연속 반복 방지)
        self._oneshots = []              # 재생 중인 원샷들 [(h, hdr, buf)]
        self._loop_bufs = {}             # 볼륨별 루프 버퍼 캐시 (매번 만들면 느리다)
        self._loop_gain = 0.5            # 현재 루프의 볼륨 (꼬리를 같은 크기로)
        self._loop_fr = self.fr          # 현재 루프의 재생 주파수 (꼬리도 같게)

    def _win_rms(self, src, win):
        return [(sum(src[i + j] * src[i + j] for j in range(win)) / win) ** 0.5
                for i in range(0, len(src) - win, win)]

    def _steady_bed(self, src):
        """긴 녹음에서 가장 고른 구간을 골라 큰 기복만 살짝 다듬는다.
        실제 스크레이프 질감은 최대한 남긴다(평탄화 약하게)."""
        fr = self.fr
        win = max(8, int(fr * 0.02))
        need = min(len(src) - 1, int(fr * self.BED_S) + int(fr * self.XFADE_S))
        rms = self._win_rms(src, win)
        wc = max(1, need // win)
        best = (1e18, 0)
        for s in range(0, max(1, len(rms) - wc)):     # RMS 변동이 가장 작은 창
            seg = rms[s:s + wc]
            mean = sum(seg) / len(seg)
            var = sum((r - mean) ** 2 for r in seg) / len(seg)
            cv = var ** 0.5 / (mean + 1e-9)
            if cv < best[0]:
                best = (cv, s * win)
        s0 = best[1]
        seg = src[s0:s0 + need]
        peak = max(1.0, max(abs(v) for v in seg))
        target, floor = 0.6 * peak, 0.45 * peak       # 약한 평탄화(±완만)
        out = []
        for i in range(0, len(seg) - win + 1, win):
            w2 = seg[i:i + win]
            r = (sum(v * v for v in w2) / win) ** 0.5
            g = min(1.8, target / max(r, floor))
            out.extend(max(-32767, min(32767, int(v * g))) for v in w2)
        return out

    def _voiced_flat(self, src):
        """짧은 클립용 폴백 — 소리 나는 창만 모아 강하게 평탄화한다."""
        win = max(8, int(self.fr * 0.012))
        rms = [(i, r) for i, r in
               zip(range(0, len(src) - win, win), self._win_rms(src, win))]
        if not rms:
            raise ValueError("펜 소리가 너무 짧음")
        peak = max(r for _, r in rms) or 1.0
        thr = 0.25
        voiced = [i for i, r in rms if r >= thr * peak]
        while len(voiced) * win < self.fr * 0.25 and thr > 0.05:
            thr -= 0.05
            voiced = [i for i, r in rms if r >= thr * peak]
        target, floor = 0.5 * peak, 0.30 * peak
        out = []
        for i in voiced:
            seg = src[i:i + win]
            r = (sum(v * v for v in seg) / win) ** 0.5
            g = target / max(r, floor)
            out.extend(max(-32767, min(32767, int(v * g))) for v in seg)
        return out

    GAIN_LEVELS = 3        # 속도별 볼륨 단계 (미리 구워 두는 가짓수)

    def set_volume(self, volume):
        """볼륨을 바꾸고, 짧은 클립 재생용 버퍼를 미리 구워 둔다.

        재생 시점(마우스 콜백)에 샘플마다 볼륨을 곱하면 후킹 스레드에서
        1만 번짜리 반복이 돌아 입력이 밀린다. 미리 만들어 두고 고르기만 한다.
        """
        self.volume = max(0.0, min(float(volume), 100.0))
        base = self.volume / 100.0
        self._short_bufs = []
        self._tail_bufs = {}
        if base <= 0.0:
            return
        for pcm in self.shorts:
            row = []
            for lv in range(self.GAIN_LEVELS):
                g = base * (0.7 + 0.3 * (lv / max(1, self.GAIN_LEVELS - 1)))
                row.append(_scaled_buffer(pcm, g, 2))
            self._short_bufs.append(row)

    def _tail_buf(self, gain):
        """루프 꼬리 버퍼 (볼륨별 캐시). 메인 스레드에서만 만든다."""
        key = round(gain, 2)
        buf = self._tail_bufs.get(key)
        if buf is None:
            if len(self._tail_bufs) > 8:
                self._tail_bufs.clear()
            buf = _scaled_buffer(self._tail_pcm, key, 2)
            self._tail_bufs[key] = buf
        return buf

    # ── 마우스 콜백에서 즉시 호출 (그리기 루프를 기다리지 않는다) ──────────
    # 펜 소리가 그리기 루프에 묶여 있으면 프레임 간격(33~66ms)만큼 늦게 난다.
    # 타자 소리처럼 입력 이벤트에서 바로 재생해야 '댄 순간' 느낌이 난다.

    def pen_down(self, x, y, now):
        """펜을 댄 순간 — 새 획 시작 (소리는 아직, 움직임을 봐야 탭과 구분된다)."""
        self._down = True
        self._stroke_dist = 0.0
        self._stroke_fired = False
        self._last_xy = (x, y)
        self._last_ev = now

    def pen_move(self, x, y, now):
        """마우스가 움직일 때마다 — MOVE_MIN을 넘는 즉시 짧은 클립을 낸다."""
        if self._last_xy is not None:
            d = math.hypot(x - self._last_xy[0], y - self._last_xy[1])
            dt = now - self._last_ev
            if 0 < dt < 0.5:
                sp = d / dt
                self._cur_speed += (sp - self._cur_speed) * 0.5   # 살짝 평활
            if d > 0.5:
                self._moving_t = now
            if self._down:
                self._stroke_dist += d
                if not self._stroke_fired and self._stroke_dist >= self.MOVE_MIN:
                    self._stroke_fired = True
                    self._stroke_t = now
                    if self.volume > 0.0:
                        self._play_short(self._cur_speed)
        self._last_xy = (x, y)
        self._last_ev = now

    def pen_up(self, now):
        """펜을 뗀 순간 — 표시만 남기고, 루프 정지는 tick(메인 스레드)에 맡긴다.

        여기서 직접 장치를 닫으면 같은 프레임에 tick도 닫으려 들어 같은
        핸들을 두 번 닫는다(access violation → 팔 구역 차단·입력 지연 사고).
        소리 장치를 여닫는 일은 메인 스레드만 하도록 못 박는다.
        """
        self._down = False
        self._stroke_fired = False

    # ── 그리기 루프에서 호출 (루프 전환·정리) ──────────────────────────────

    def tick(self, now, enabled=True):
        """프레임마다 호출 — 끝난 소리를 거두고 긴 획이면 루프로 넘어간다."""
        self._reap()
        want = (enabled and self._down and self._stroke_fired
                and now - self._moving_t < 0.18
                and now - self._stroke_t > self.SHORT_MAX)
        if want and not self._playing and self.volume > 0.0:
            self._start()
        elif self._playing and not want:
            self._stop_loop(tail=True)

    def _pick_short(self, speed):
        """속도에 맞는 클립 고르기 — 빠르면 짧고 경쾌한 것, 느리면 긴 것.
        (shorts는 길이순 정렬) 직전과 같은 것은 피해 반복감을 줄인다."""
        n = len(self.shorts)
        half = max(1, n // 2)
        pool = range(0, half) if speed >= 350.0 else range(n - half, n)
        cand = [i for i in pool if i != self._last_pick] or list(pool)
        i = random.choice(cand)
        self._last_pick = i
        return i

    def _oneshot(self, buf, nbytes, fr2):
        """이미 볼륨이 반영된 버퍼를 독립 장치로 재생한다.

        마우스 콜백(후킹 스레드)에서도 불리므로 무거운 계산을 하지 않는다 —
        볼륨 곱하기는 set_volume에서 미리 구워 둔다. 후킹 스레드가 늦어지면
        윈도우가 시스템 전체의 펜/마우스 이벤트를 지연시켜, 그림 선이
        직선으로 이어지고 타자가 굼떠지는 사고가 난다.
        """
        wfx = _WAVEFORMATEX(1, 1, fr2, fr2 * 2, 2, 16, 0)
        wm = ctypes.windll.winmm
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF, ctypes.byref(wfx), 0, 0, 0):
            return
        wm.waveOutSetVolume(h, 0xFFFFFFFF)   # 장치 볼륨은 만땅 고정 — 이후 안 건드린다
        hdr = _WAVEHDR()
        hdr.lpData = ctypes.cast(buf, ctypes.c_void_p)
        hdr.dwBufferLength = nbytes
        wm.waveOutPrepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        with self._lock:                     # 회수 목록은 메인 스레드와 공유
            self._oneshots.append((h, hdr, buf))

    def _play_short(self, speed):
        """짧은 클립 하나를 즉시 재생 (미리 구워 둔 버퍼를 고르기만 한다)."""
        if not self._short_bufs:
            return
        i = self._pick_short(speed)
        g = max(0.0, min(1.0, (speed - 30.0) / 500.0))
        lv = min(self.GAIN_LEVELS - 1, int(g * self.GAIN_LEVELS))
        fr2 = max(8000, int(self.fr * random.uniform(0.97, 1.06)))
        self._oneshot(self._short_bufs[i][lv], len(self.shorts[i]), fr2)

    def _reap(self):
        """끝난 원샷(짧은 클립·루프 꼬리)을 회수한다 (메인 스레드 전용)."""
        with self._lock:
            if not self._oneshots:
                return
            pending, self._oneshots = self._oneshots, []
        wm = ctypes.windll.winmm
        keep = []
        for h, hdr, buf in pending:
            if hdr.dwFlags & 0x00000001:        # WHDR_DONE
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            else:
                keep.append((h, hdr, buf))
        with self._lock:                        # 회수 중 새로 들어온 것과 합친다
            self._oneshots = keep + self._oneshots

    def _loop_buf(self, gain):
        """볼륨별 루프 본체 버퍼 (1.5초짜리라 매번 만들면 프레임을 잡아먹는다)."""
        key = round(gain, 2)
        buf = self._loop_bufs.get(key)
        if buf is None:
            if len(self._loop_bufs) > 8:
                self._loop_bufs.clear()
            buf = _scaled_buffer(self.loop_pcm, key, 2)
            self._loop_bufs[key] = buf
        return buf

    def _start(self):
        """루프 시작 — 페이드인이 구워진 머리를 먼저, 이어서 본체를 무한 반복."""
        g = max(0.0, min(1.0, (self._cur_speed - 30.0) / 500.0))   # 속도 0~1
        gain = (self.volume / 100.0) * (0.6 + 0.4 * g)
        self._loop_gain = gain
        fr2 = max(8000, int(self.fr * random.uniform(0.95, 1.08)))  # 획마다 피치만
        self._loop_fr = fr2
        wfx = _WAVEFORMATEX(1, 1, fr2, fr2 * 2, 2, 16, 0)
        wm = ctypes.windll.winmm
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF, ctypes.byref(wfx), 0, 0, 0):
            return
        wm.waveOutSetVolume(h, 0xFFFFFFFF)     # 만땅 고정 — 페이드는 샘플에 있다
        head_buf = _scaled_buffer(self._head_pcm, gain, 2)
        hh = _WAVEHDR()                         # 1) 페이드인 머리 (한 번)
        hh.lpData = ctypes.cast(head_buf, ctypes.c_void_p)
        hh.dwBufferLength = len(self._head_pcm)
        wm.waveOutPrepareHeader(h, ctypes.byref(hh), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hh), ctypes.sizeof(_WAVEHDR))
        body_buf = self._loop_buf(gain)
        hb = _WAVEHDR()                         # 2) 본체 (멈출 때까지 무한 반복)
        hb.lpData = ctypes.cast(body_buf, ctypes.c_void_p)
        hb.dwBufferLength = len(self.loop_pcm)
        hb.dwFlags = 0x00000004 | 0x00000008    # WHDR_BEGINLOOP | WHDR_ENDLOOP
        hb.dwLoops = 0xFFFFFFFF
        wm.waveOutPrepareHeader(h, ctypes.byref(hb), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hb), ctypes.sizeof(_WAVEHDR))
        with self._lock:
            self._voice = (h, hh, hb, head_buf, body_buf)
            self._playing = True

    def _stop_loop(self, tail=True):
        """루프를 멈춘다. tail이면 페이드아웃 꼬리를 따로 재생해 부드럽게 끝낸다.

        **핸들을 먼저 꺼내 놓고(_voice=None) 그 다음에 닫는다.** 반대로 하면
        두 곳에서 동시에 들어왔을 때 같은 핸들을 두 번 닫아 access violation이
        난다. 꺼내기를 원자적으로 하면 두 번 닫는 일이 구조적으로 불가능하다.
        """
        with self._lock:
            voice, self._voice = self._voice, None
            self._playing = False
        if voice is None:
            return
        wm = ctypes.windll.winmm
        h, hh, hb, _hbuf, _bbuf = voice
        try:
            wm.waveOutReset(h)                  # 무한 반복 중단
            for hdr in (hh, hb):
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr),
                                          ctypes.sizeof(_WAVEHDR))
            wm.waveOutClose(h)
        except Exception:
            pass                                # 이미 닫혔어도 여기서 끝낸다
        if tail and self.volume > 0.0:          # 꼬리는 별도 장치 — 볼륨 간섭 없음
            buf = self._tail_buf(self._loop_gain)
            self._oneshot(buf, len(self._tail_pcm), self._loop_fr)

    def stop(self):
        self._stop_loop(tail=False)

    def close(self):
        """캐릭터 종료 시 — 재생 중인 것을 전부 정리한다."""
        self._stop_loop(tail=False)
        with self._lock:
            pending, self._oneshots = self._oneshots, []
        wm = ctypes.windll.winmm
        for h, hdr, _b in pending:
            try:
                wm.waveOutReset(h)
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            except Exception:
                pass


class _MacSoundPool:
    """macOS 소리 재생 — NSSound 사본을 돌려가며 겹쳐 재생한다.

    winmm(waveOut)은 윈도우 전용이라 맥에서는 AppKit의 NSSound를 쓴다.
    같은 NSSound를 연속 호출하면 이어붙지 않고 다시 시작되므로, 파일마다
    사본을 몇 개 두고 번갈아 재생해 타자처럼 빠른 연타도 겹치게 한다.
    """

    COPIES = 3

    def __init__(self, paths, volume):
        from AppKit import NSSound
        self.pool = []
        for p in paths:
            row = []
            for _ in range(self.COPIES):
                snd = NSSound.alloc().initWithContentsOfFile_byReference_(p, True)
                if snd is not None:
                    row.append(snd)
            if row:
                self.pool.append(row)
        if not self.pool:
            raise ValueError("재생 가능한 wav가 없음")
        self._turn = [0] * len(self.pool)
        self.set_volume(volume)

    def set_volume(self, volume):
        self.volume = max(0.0, min(float(volume), 100.0))
        g = self.volume / 100.0
        for row in self.pool:
            for snd in row:
                try:
                    snd.setVolume_(g)
                except Exception:
                    pass

    def _fire(self, idx):
        if self.volume <= 0 or not self.pool:
            return
        row = self.pool[idx % len(self.pool)]
        snd = row[self._turn[idx % len(self.pool)] % len(row)]
        self._turn[idx % len(self.pool)] += 1
        try:
            if snd.isPlaying():
                snd.stop()
            snd.play()
        except Exception:
            pass

    def _all_stop(self):
        for row in self.pool:
            for snd in row:
                try:
                    snd.stop()
                except Exception:
                    pass


class MacSoundPack(_MacSoundPool):
    """맥용 Mechvibes 팩 재생기 (SoundPack과 같은 인터페이스).

    맥은 어느 키를 눌렀는지 알 수 없어(카운터만 읽는다) 키별 구분은 못 한다.
    인자만 맞춰 두고 무시한다.
    """

    def __init__(self, folder, volume=60):
        with open(os.path.join(folder, "config.json"), encoding="utf-8") as fp:
            cfg = json.load(fp)
        if cfg.get("key_define_type", "multi") != "multi":
            raise ValueError("single 타입 팩 미지원")
        names, paths = [], []
        for v in cfg.get("defines", {}).values():
            if isinstance(v, str) and v and v not in names:
                names.append(v)
        for name in names:
            p = os.path.join(folder, name)
            if name.lower().endswith(".wav") and os.path.exists(p):
                paths.append(p)
        super().__init__(paths, volume)

    def play(self, key, code=None):
        # **인자를 둘 받아야 한다.** 부르는 쪽은 늘
        # `sp.play(key, self._scan_code(key))` 이고, 그 자리는
        # `except Exception: pass` 로 감싸여 있어서 맞지 않으면 **아무 소리도
        # 안 나면서 아무 자국도 안 남는다** — 맥에서 타자 소리가 한 번도
        # 안 났던 원인 (사가 제보). 맥은 어느 키인지 몰라 code 는 안 쓴다.
        self._fire(hash(str(key)) % max(len(self.pool), 1))

    def reap(self):
        pass                      # NSSound는 스스로 정리된다

    def close(self):
        self._all_stop()


class MacPenSound(_MacSoundPool):
    """맥용 펜 긋는 소리 (PenSound와 같은 인터페이스)."""

    def __init__(self, folder, volume=35):
        names = [f for f in sorted(os.listdir(folder)) if f.lower().endswith(".wav")]
        clips = [f for f in names if f.lower().startswith("clip")] or names
        paths = [os.path.join(folder, f) for f in clips]
        if not paths:
            raise ValueError("펜 소리 wav 없음")
        super().__init__(paths, volume)

    def play(self):
        self._fire(random.randrange(len(self.pool)))

    def stop(self):
        self._all_stop()


class PokeSound:
    """캐릭터를 눌렀을 때 나는 짧은 소리.

    누르는 건 잦아서 같은 소리가 그대로 반복되면 금방 물린다. 그래서 매번
    재생 속도를 조금씩 흔들어 음높이를 달리한다. 볼륨은 미리 곱해 두고
    (waveOutSetVolume은 드라이버가 무시할 수 있다) 재생 때는 고르기만 한다.
    """

    def __init__(self, folder, volume=40, only=None):
        """only 를 주면 그 파일 하나만 읽는다.

        한 폴더에 뜻이 다른 소리가 같이 있을 때 쓴다 — 뽀모도로의
        시작음·종료음을 한 묶음에 넣으면 랜덤으로 골라 나와서, 집중이
        시작될 때 종료음이 날 수 있다.
        """
        import wave
        names = [f for f in sorted(os.listdir(folder)) if f.lower().endswith(".wav")]
        if only:
            names = [f for f in names if f == only]
        if not names:
            raise ValueError("클릭 소리 wav 없음")
        # 폴더에 여럿이면 다 읽어 두고 번갈아 낸다 (홈 반응 소리가 둘이다).
        self.clips = []
        for nm in names:
            with wave.open(os.path.join(folder, nm), "rb") as w:
                if w.getsampwidth() != 2 or w.getnchannels() != 1:
                    continue          # 16bit 모노가 아니면 건너뛴다
                self.clips.append((w.getframerate(),
                                   w.readframes(w.getnframes())))
        if not self.clips:
            raise ValueError("클릭 소리는 16bit 모노 wav만 지원")
        self.fr, self.pcm = self.clips[0]
        self._voices = []
        self.set_volume(volume)

    def set_volume(self, volume):
        self.volume = max(0.0, min(float(volume), 100.0))
        self.bufs = ([(fr, _scaled_buffer(pcm, self.volume / 100.0, 2), len(pcm))
                      for fr, pcm in self.clips] if self.volume > 0 else [])
        self.buf = self.bufs[0][1] if self.bufs else None

    def play(self, pitch=1.0):
        """pitch 를 주면 그만큼 낮게·높게 낸다 (1.0 이 원래 높이).

        수박게임이 공 크기에 맞춰 쓴다 — 큰 공은 낮고 무겁게, 작은 공은
        높고 가볍게. 안 주면 예전 그대로 랜덤 변주만 걸린다.
        """
        self.reap()
        if not getattr(self, "bufs", None):
            return
        fr, buf, nbytes = random.choice(self.bufs)
        try:
            pitch = max(0.35, min(2.2, float(pitch)))
        except Exception:
            pitch = 1.0
        fr2 = max(8000, int(fr * pitch * random.uniform(0.96, 1.05)))
        wfx = _WAVEFORMATEX(1, 1, fr2, fr2 * 2, 2, 16, 0)
        wm = ctypes.windll.winmm
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF, ctypes.byref(wfx), 0, 0, 0):
            return
        wm.waveOutSetVolume(h, 0xFFFFFFFF)     # 실볼륨은 샘플에 이미 반영됨
        hdr = _WAVEHDR()
        hdr.lpData = ctypes.cast(buf, ctypes.c_void_p)
        hdr.dwBufferLength = nbytes
        wm.waveOutPrepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        # 여기도 같은 이유로 버퍼를 함께 붙든다 (set_volume이
        # 버퍼를 갈아 끼우는 동안 옛 소리가 재생 중일 수 있다)
        self._voices.append((h, hdr, buf))

    def reap(self):
        wm = ctypes.windll.winmm
        keep = []
        for h, hdr, _b in self._voices:
            if hdr.dwFlags & 0x00000001:        # WHDR_DONE
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            else:
                keep.append((h, hdr, _b))
        self._voices = keep

    def _all_stop(self):
        """울리고 있는 소리를 그 자리에서 끊는다 (고롱고롱이 쓴다).

        버퍼·클립은 그대로 두므로 곧바로 다시 `play()` 할 수 있다.
        맥 쪽(`_MacSoundPool`)에도 같은 이름이 있어 부르는 쪽은 갈래를
        나누지 않는다.
        """
        wm = ctypes.windll.winmm
        for h, hdr, _b in self._voices:
            try:
                wm.waveOutReset(h)
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr),
                                          ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            except Exception:
                pass
        self._voices = []

    def close(self):
        self._all_stop()


class MacPokeSound(_MacSoundPool):
    """맥용 클릭 소리 (PokeSound와 같은 인터페이스).

    맥은 재생 속도를 못 바꿔서 피치 인자를 받아만 두고 무시한다 —
    부르는 쪽이 갈래를 나누지 않게 하려는 것이다.
    """

    def __init__(self, folder, volume=40):
        names = [f for f in sorted(os.listdir(folder)) if f.lower().endswith(".wav")]
        if not names:
            raise ValueError("클릭 소리 wav 없음")
        super().__init__([os.path.join(folder, names[0])], volume)

    def play(self, pitch=1.0):
        self._fire(0)

    def close(self):
        self._all_stop()


class SlimeSound:
    """슬라임을 만질 때 나는 소리 — 종류별로 여러 장을 두고 골라 낸다.

    PokeSound와 같은 방식(볼륨은 샘플에 미리 곱해 두고, 재생 속도를 흔들어
    음높이를 달리한다)이지만 누르기·늘리기·구슬처럼 종류가 여럿이다.
    파일 이름 앞머리로 묶으므로 press1.wav / crunch2.wav 처럼 두면 된다.

    끄는 세기에 따라 소리 크기가 달라져야 해서 세 단계로 미리 만들어 둔다.
    waveOutSetVolume은 드라이버가 무시할 수 있어 믿을 수 없기 때문이다.
    """

    KINDS = ("press", "stretch", "pop", "crunch", "unroll")
    LEVELS = (0.35, 0.62, 1.0)
    MAX_VOICES = 4               # 동시에 나는 소리 상한 (연타해도 안 뭉개지게)
    # 종류별 상한과 최소 간격. 누르는 소리는 종류에 따라 400ms까지 가는데,
    # 빨리 누르면 그게 죄다 겹쳐 웅웅거린다. 한 가지 소리는 둘까지만,
    # 그것도 이 간격은 띄우고 낸다.
    SAME_MAX = {"press": 2, "pop": 2, "stretch": 3, "crunch": 2, "unroll": 1}
    MIN_GAP = {"press": 0.13, "pop": 0.13, "stretch": 0.05,
               "crunch": 0.07, "unroll": 0.40}

    def __init__(self, folder, volume=45):
        import wave
        self.clips = {}
        for name in sorted(os.listdir(folder)):
            if not name.lower().endswith(".wav"):
                continue
            kind = os.path.splitext(name)[0].rstrip("0123456789")
            if kind not in self.KINDS:
                continue
            with wave.open(os.path.join(folder, name), "rb") as w:
                if w.getsampwidth() != 2 or w.getnchannels() != 1:
                    continue
                fr = w.getframerate()
                pcm = w.readframes(w.getnframes())
            # 재생 속도는 소리마다 따로 들고 있는다. 하나로 뭉뚱그리면 종류를
            # 바꿨을 때(44.1kHz ↔ 48kHz) 음이 통째로 어긋난다.
            self.clips.setdefault(kind, []).append((pcm, fr))
        if not self.clips:
            raise ValueError("슬라임 소리 wav 없음")
        self._voices = []            # (핸들, 헤더, 종류)
        self._bufs = {}
        self._last = {}              # 종류별 마지막으로 낸 시각
        self.set_volume(volume)

    def set_volume(self, volume):
        self.volume = max(0.0, min(float(volume), 100.0))
        self._bufs = {}              # 볼륨이 바뀌면 미리 만든 것을 버린다

    def _buf(self, kind, idx, level):
        key = (kind, idx, level)
        hit = self._bufs.get(key)
        if hit is None:
            pcm, fr = self.clips[kind][idx]
            g = self.volume / 100.0 * self.LEVELS[level]
            hit = (_scaled_buffer(pcm, g, 2), len(pcm), fr)
            self._bufs[key] = hit
        return hit

    def has(self, kind):
        return kind in self.clips

    def play(self, kind, pitch=1.0, level=2):
        self.reap()
        if self.volume <= 0 or kind not in self.clips:
            return
        if len(self._voices) >= self.MAX_VOICES:
            return
        # 같은 소리가 겹쳐 웅웅거리지 않게 — 간격과 개수를 함께 막는다
        now = time.time()
        if now - self._last.get(kind, 0.0) < self.MIN_GAP.get(kind, 0.08):
            return
        if (sum(1 for v in self._voices if v[2] == kind)
                >= self.SAME_MAX.get(kind, 2)):
            return
        self._last[kind] = now
        idx = random.randrange(len(self.clips[kind]))
        buf, ln, fr = self._buf(kind, idx,
                                max(0, min(len(self.LEVELS) - 1, int(level))))
        fr2 = max(8000, int(fr * pitch * random.uniform(0.94, 1.07)))
        wfx = _WAVEFORMATEX(1, 1, fr2, fr2 * 2, 2, 16, 0)
        wm = ctypes.windll.winmm
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF, ctypes.byref(wfx), 0, 0, 0):
            return
        wm.waveOutSetVolume(h, 0xFFFFFFFF)     # 실볼륨은 샘플에 이미 반영됨
        hdr = _WAVEHDR()
        hdr.lpData = ctypes.cast(buf, ctypes.c_void_p)
        hdr.dwBufferLength = ln
        wm.waveOutPrepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        wm.waveOutWrite(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
        # 버퍼를 voice에 함께 담아 둔다. 헤더는 날 포인터만 들고 있어서,
        # 재생 중에 _bufs가 비워지면(볼륨 변경·종류 교체) 드라이버가
        # 이미 없는 메모리를 읽어 프로세스가 통째로 죽는다.
        self._voices.append((h, hdr, kind, buf))

    def reap(self):
        wm = ctypes.windll.winmm
        keep = []
        for h, hdr, kind, buf in self._voices:
            if hdr.dwFlags & 0x00000001:        # WHDR_DONE
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            else:
                keep.append((h, hdr, kind, buf))
        self._voices = keep

    def close(self):
        wm = ctypes.windll.winmm
        for h, hdr, _k, _b in self._voices:
            try:
                wm.waveOutReset(h)
                wm.waveOutUnprepareHeader(h, ctypes.byref(hdr), ctypes.sizeof(_WAVEHDR))
                wm.waveOutClose(h)
            except Exception:
                pass
        self._voices = []


class MacSlimeSound(_MacSoundPool):
    """맥용 슬라임 소리 (SlimeSound와 같은 인터페이스). 음높이 변주는 없다."""

    # 아래에서 SlimeSound라는 이름 자체를 이 클래스로 바꿔 끼우므로, 메서드
    # 안에서 SlimeSound.KINDS를 찾으면 자기 자신을 보게 된다. 클래스를 만드는
    # 지금(아직 윈도우용을 가리킬 때) 붙잡아 둔다.
    KINDS = SlimeSound.KINDS

    def __init__(self, folder, volume=45):
        names = [f for f in sorted(os.listdir(folder)) if f.lower().endswith(".wav")]
        self.idx = {}
        paths = []
        for name in names:
            kind = os.path.splitext(name)[0].rstrip("0123456789")
            if kind not in self.KINDS:
                continue
            self.idx.setdefault(kind, []).append(len(paths))
            paths.append(os.path.join(folder, name))
        if not paths:
            raise ValueError("슬라임 소리 wav 없음")
        super().__init__(paths, volume)

    def has(self, kind):
        return kind in self.idx

    def play(self, kind, pitch=1.0, level=2):
        row = self.idx.get(kind)
        if row:
            self._fire(random.choice(row))

    def close(self):
        self._all_stop()


class AmbientSound:
    """환경음(BGM) — 여러 소리를 동시에, 끄기 전까지 끝없이.

    파일을 통째로 올리지 않고 **조각으로 흘려보낸다**. 통째로 올려 볼륨을
    곱하던 때는 3분짜리 하나에 메모리 60MB 와 곱셈 3천만 번이 들어, 켜는
    순간 화면과 커서가 1.6초 굳었다(실측). 지금은 0.4초짜리 조각 넷을
    돌려 쓴다 — 파일이 한 시간이어도 메모리는 300KB, 한 번에 곱하는 것도
    조각 하나치뿐이다.

    볼륨도 이 구조라서 공짜다. **다음 조각부터** 새 볼륨으로 채우면 되니
    소리가 안 끊기고 되감기지도 않는다. 장치 볼륨(waveOutSetVolume)은
    쓸 수 없다 — 그건 핸들이 아니라 장치의 볼륨이라, 다른 소리가 재생
    직전에 최대로 되돌릴 때마다 환경음까지 커진다(실측으로 확인).

    채우는 일은 스레드 하나가 모든 소리를 돌며 맡는다. 조각이 다 나가기
    전에 다음 것을 넣어 두므로 끊기지 않는다.
    """

    CHUNK_SEC = 0.4           # 조각 하나의 길이
    SLOTS = 4                 # 돌려 쓰는 조각 수 (1.6초치 여유)
    TICK = 0.06               # 채우러 도는 간격

    def __init__(self, folder):
        import threading
        import wave                            # (이미 쓰는 표준 모듈)
        self.folder = folder
        self.names = [os.path.splitext(f)[0]
                      for f in sorted(os.listdir(folder))
                      if f.lower().endswith(".wav")]
        if not self.names:
            raise ValueError("환경음 wav 없음")
        self._wave = wave
        self._threading = threading
        self._lock = threading.Lock()
        self.tracks = {}          # 이름 -> 흐르고 있는 소리 한 벌
        self.want = {}            # 이름 -> 바라는 볼륨
        self._stop = False
        self._th = threading.Thread(target=self._loop, daemon=True)
        self._th.start()

    # ── 한 소리 열기/닫기 ───────────────────────────────────────────────
    def _open(self, name, vol):
        path = os.path.join(self.folder, name + ".wav")
        wf = self._wave.open(path, "rb")
        ch, sw, fr = wf.getnchannels(), wf.getsampwidth(), wf.getframerate()
        if sw != 2:
            wf.close()
            raise ValueError("환경음은 16bit wav 만 지원")
        wfx = _WAVEFORMATEX(1, ch, fr, fr * ch * sw, ch * sw, sw * 8, 0)
        wm = ctypes.windll.winmm
        h = ctypes.c_void_p()
        if wm.waveOutOpen(ctypes.byref(h), 0xFFFFFFFF,
                          ctypes.byref(wfx), 0, 0, 0):
            wf.close()
            raise OSError("소리 장치를 열 수 없음")
        nframe = max(1024, int(fr * self.CHUNK_SEC))
        nbytes = nframe * ch * sw
        slots = []
        for _ in range(self.SLOTS):
            buf = ctypes.create_string_buffer(nbytes)
            hdr = _WAVEHDR()
            hdr.lpData = ctypes.cast(buf, ctypes.c_void_p)
            hdr.dwBufferLength = nbytes
            hdr.dwFlags = 0
            wm.waveOutPrepareHeader(h, ctypes.byref(hdr),
                                    ctypes.sizeof(_WAVEHDR))
            hdr.dwFlags |= 0x00000001          # WHDR_DONE — 처음엔 다 비었다
            slots.append([hdr, buf, False])    # [헤더, 버퍼, 나가 있는가]
        return {"h": h, "wf": wf, "slots": slots, "nframe": nframe,
                "vol": float(vol), "ch": ch, "sw": sw, "fr": fr,
                "played": 0}

    def _close_track(self, tr):
        wm = ctypes.windll.winmm
        try:
            wm.waveOutReset(tr["h"])
            for hdr, _buf, _out in tr["slots"]:
                wm.waveOutUnprepareHeader(tr["h"], ctypes.byref(hdr),
                                          ctypes.sizeof(_WAVEHDR))
            wm.waveOutClose(tr["h"])
        except Exception:
            pass
        try:
            tr["wf"].close()
        except Exception:
            pass

    # ── 채우기 ──────────────────────────────────────────────────────────
    def _fill(self, tr):
        """빈 조각을 다음 소리로 채워 다시 내보낸다 (끝나면 처음으로)."""
        wm = ctypes.windll.winmm
        g = max(0.0, min(tr["vol"], 100.0)) / 100.0
        step = tr["nframe"]
        for slot in tr["slots"]:
            hdr, buf, out = slot
            if out and not (hdr.dwFlags & 0x00000001):    # 아직 나가 있다
                continue
            data = tr["wf"].readframes(step)
            if len(data) < hdr.dwBufferLength:
                tr["wf"].rewind()                          # 끝 → 처음으로
                data += tr["wf"].readframes(
                    step - len(data) // (tr["ch"] * tr["sw"]))
            if not data:
                return
            n = len(data)
            ctypes.memmove(buf, data, n)
            if g < 0.999:
                arr = (ctypes.c_int16 * (n // 2)).from_buffer(buf)
                for i in range(n // 2):
                    arr[i] = int(arr[i] * g)
            hdr.dwBufferLength = n
            hdr.dwFlags &= ~0x00000001                     # DONE 을 지운다
            wm.waveOutWrite(tr["h"], ctypes.byref(hdr),
                            ctypes.sizeof(_WAVEHDR))
            slot[2] = True
            tr["played"] += n

    def _loop(self):
        import time as _t
        while not self._stop:
            try:
                with self._lock:
                    for name in list(self.tracks):
                        self._fill(self.tracks[name])
            except Exception:
                pass
            _t.sleep(self.TICK)

    # ── 바깥에서 쓰는 것들 ──────────────────────────────────────────────
    def has(self, name):
        return str(name) in self.names

    def is_on(self, name):
        return str(name) in self.want

    def on_names(self):
        return sorted(self.want)

    def played_bytes(self, name):
        """지금까지 내보낸 바이트 (검사에서 '진짜 흐르는가'를 볼 때)."""
        tr = self.tracks.get(str(name or ""))
        return int(tr["played"]) if tr else -1

    def set(self, name, on, vol=35):
        """켜거나 끈다. 켜져 있으면 볼륨만 바꾼다 (안 끊긴다)."""
        name = str(name or "")
        if name not in self.names:
            return
        vol = max(0.0, min(float(vol), 100.0))
        if not on or vol <= 0:
            self.stop(name)
            return
        with self._lock:
            self.want[name] = vol
            tr = self.tracks.get(name)
            if tr is not None:
                tr["vol"] = vol            # 다음 조각부터 새 볼륨
                return
            try:
                tr = self._open(name, vol)
            except Exception:
                self.want.pop(name, None)
                return
            self.tracks[name] = tr
            self._fill(tr)                 # 첫 조각은 그 자리에서 채운다

    def vol(self, name, vol):
        self.set(name, True, vol)

    def stop(self, name):
        name = str(name or "")
        with self._lock:
            self.want.pop(name, None)
            tr = self.tracks.pop(name, None)
        if tr is not None:
            self._close_track(tr)

    def stop_all(self):
        for name in list(self.want) + list(self.tracks):
            self.stop(name)

    def close(self):
        self._stop = True
        self.stop_all()


class MacAmbientSound:
    """맥용 환경음 — NSSound 에 반복 재생을 맡긴다 (같은 인터페이스)."""

    def __init__(self, folder):
        from AppKit import NSSound            # noqa: F401  (있는지 확인만)
        self.folder = folder
        self.names = [os.path.splitext(f)[0]
                      for f in sorted(os.listdir(folder))
                      if f.lower().endswith(".wav")]
        if not self.names:
            raise ValueError("환경음 wav 없음")
        self.voices = {}

    def has(self, name):
        return str(name) in self.names

    def on_names(self):
        return sorted(self.voices)

    def is_on(self, name):
        return str(name) in self.voices

    def set(self, name, on, vol=35):
        name = str(name or "")
        if name not in self.names:
            return
        if not on:
            self.stop(name)
            return
        if name in self.voices:
            self.vol(name, vol)
            return
        if float(vol) <= 0:
            return
        from AppKit import NSSound
        path = os.path.join(self.folder, name + ".wav")
        snd = NSSound.alloc().initWithContentsOfFile_byReference_(path, True)
        if snd is None:
            return
        snd.setLoops_(True)
        snd.setVolume_(max(0.0, min(float(vol), 100.0)) / 100.0)
        snd.play()
        self.voices[name] = snd

    def vol(self, name, vol):
        snd = self.voices.get(str(name or ""))
        if snd is None:
            return
        if float(vol) <= 0:
            self.stop(name)
            return
        try:
            snd.setVolume_(max(0.0, min(float(vol), 100.0)) / 100.0)
        except Exception:
            pass

    def stop(self, name):
        snd = self.voices.pop(str(name or ""), None)
        if snd is not None:
            try:
                snd.stop()
            except Exception:
                pass

    def stop_all(self):
        for name in list(self.voices):
            self.stop(name)

    def close(self):
        self.stop_all()


if IS_MAC:                        # 맥에서는 같은 이름으로 맥 구현을 쓴다
    SoundPack, PenSound, PokeSound = MacSoundPack, MacPenSound, MacPokeSound
    SlimeSound = MacSlimeSound
    AmbientSound = MacAmbientSound


if IS_WIN:
    ctypes.windll.user32.MonitorFromPoint.argtypes = [_POINT, ctypes.c_uint32]
    ctypes.windll.user32.MonitorFromPoint.restype = ctypes.c_void_p

_TK_ROOT = None                  # 맥에서 커서·화면 크기를 Tk로 얻기 위한 참조


class MacInput:
    """맥 입력 감지 — 리스너 스레드 대신 CoreGraphics 카운터를 매 프레임 읽는다.

    운영체제가 세어 둔 이벤트 개수를 그냥 조회하는 방식이라
      · 백그라운드 스레드가 없고 (크래시 원인 제거)
      · 손쉬운 사용 권한이 필요 없으며
      · 어느 스레드에서 불러도 안전하다.
    어떤 키가 눌렸는지는 알 수 없지만, 이 프로그램은 '몇 번 눌렸는가'만 쓴다.
    """

    HID = 1                      # kCGEventSourceStateHIDSystemState (실제 하드웨어)
    KEY_DOWN = 10
    MOVED, L_DRAG, R_DRAG = 5, 6, 7

    def __init__(self):
        cg = _MAC_CG
        if cg is None:
            raise RuntimeError("CoreGraphics 없음")
        cg.CGEventSourceCounterForEventType.restype = ctypes.c_uint32
        cg.CGEventSourceCounterForEventType.argtypes = [ctypes.c_uint32,
                                                        ctypes.c_uint32]
        cg.CGEventSourceButtonState.restype = ctypes.c_bool
        cg.CGEventSourceButtonState.argtypes = [ctypes.c_uint32, ctypes.c_uint32]
        self.cg = cg
        self.keys = self._count(self.KEY_DOWN)
        self.moves = self._moves()

    def _count(self, ev):
        return int(self.cg.CGEventSourceCounterForEventType(self.HID, ev))

    def _moves(self):
        return sum(self._count(e) for e in (self.MOVED, self.L_DRAG, self.R_DRAG))

    def read(self):
        """(눌린 키 수, 커서 움직임 수, 왼쪽 버튼 눌림) — 지난 호출 이후 변화량."""
        keys, moves = self._count(self.KEY_DOWN), self._moves()
        dk, self.keys = max(keys - self.keys, 0), keys
        dm, self.moves = max(moves - self.moves, 0), moves
        return dk, dm, bool(self.cg.CGEventSourceButtonState(self.HID, 0))


def cursor_pos():
    if IS_WIN:
        pt = _POINT()
        ctypes.windll.user32.GetCursorPos(ctypes.byref(pt))
        return pt.x, pt.y
    if _TK_ROOT is not None:      # 맥: Tk가 전역 커서 좌표를 알려준다
        try:
            return _TK_ROOT.winfo_pointerxy()
        except Exception:
            pass
    return 0, 0


def idle_seconds():
    """마지막 입력(마우스·키보드·펜) 이후 경과 초."""
    try:
        if IS_WIN:
            info = _LASTINPUTINFO()
            info.cbSize = ctypes.sizeof(_LASTINPUTINFO)
            ctypes.windll.user32.GetLastInputInfo(ctypes.byref(info))
            return max(ctypes.windll.kernel32.GetTickCount() - info.dwTime, 0) / 1000.0
        if _MAC_CG is not None:
            # kCGEventSourceStateCombinedSessionState=0, kCGAnyInputEventType=0xFFFFFFFF
            return float(_MAC_CG.CGEventSourceSecondsSinceLastEventType(
                0, 0xFFFFFFFF))
    except Exception:
        pass
    return 0.0


def foreground_process():
    """앞에 떠 있는 창의 프로세스 실행파일 이름 (소문자). 실패 시 ''."""
    try:
        if IS_WIN:
            u, k = ctypes.windll.user32, ctypes.windll.kernel32
            hwnd = u.GetForegroundWindow()
            pid = ctypes.c_ulong()
            u.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            h = k.OpenProcess(0x1000, False, pid.value)  # QUERY_LIMITED_INFO
            if not h:
                return ""
            try:
                buf = ctypes.create_unicode_buffer(260)
                size = ctypes.c_ulong(260)
                if k.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size)):
                    return os.path.basename(buf.value).lower()
            finally:
                k.CloseHandle(h)
        elif IS_MAC:
            return _mac_front_app()
    except Exception:
        pass
    return ""


def _mac_front_app():
    """맨 앞 앱 이름 (소문자). PyObjC가 있으면 그걸로, 없으면 빈 문자열."""
    try:
        from AppKit import NSWorkspace
        app = NSWorkspace.sharedWorkspace().frontmostApplication()
        if app is None:
            return ""
        name = app.localizedName() or app.bundleIdentifier() or ""
        return str(name).lower()
    except Exception:
        return ""


def mac_monitors():
    """맥에 붙어 있는 화면들의 사각형 목록.

    파이썬 추가 설치 없이 CoreGraphics를 직접 불러 쓴다. 실패하면 빈 목록을
    돌려주고, 부르는 쪽이 예전처럼 주 화면 하나로 넘어간다.
    """
    out = []
    if not IS_MAC:
        return out

    class _CGPoint(ctypes.Structure):
        _fields_ = [("x", ctypes.c_double), ("y", ctypes.c_double)]

    class _CGSize(ctypes.Structure):
        _fields_ = [("w", ctypes.c_double), ("h", ctypes.c_double)]

    class _CGRect(ctypes.Structure):
        _fields_ = [("origin", _CGPoint), ("size", _CGSize)]

    for path in ("/System/Library/Frameworks/CoreGraphics.framework/CoreGraphics",
                 "/System/Library/Frameworks/ApplicationServices.framework"
                 "/ApplicationServices"):
        try:
            cg = ctypes.cdll.LoadLibrary(path)
            n = ctypes.c_uint32(0)
            ids = (ctypes.c_uint32 * 16)()
            cg.CGGetActiveDisplayList.argtypes = [
                ctypes.c_uint32, ctypes.POINTER(ctypes.c_uint32 * 16),
                ctypes.POINTER(ctypes.c_uint32)]
            if cg.CGGetActiveDisplayList(16, ctypes.byref(ids),
                                         ctypes.byref(n)) != 0:
                continue
            cg.CGDisplayBounds.argtypes = [ctypes.c_uint32]
            cg.CGDisplayBounds.restype = _CGRect
            got = []
            for i in range(min(n.value, 16)):
                r = cg.CGDisplayBounds(ids[i])
                x, y = int(round(r.origin.x)), int(round(r.origin.y))
                w, h = int(round(r.size.w)), int(round(r.size.h))
                if w > 0 and h > 0:
                    got.append((x, y, x + w, y + h))
            if got:
                out = got
                break
        except Exception:
            continue
    return out


def list_monitors():
    """붙어 있는 화면들의 사각형 목록 — 왼쪽 위부터 차례로.

    듀얼 모니터에서 '어느 화면의 마우스를 따라갈지' 고르게 하려고 쓴다.
    """
    out = []
    if IS_WIN:
        try:
            proto = ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p,
                                       ctypes.c_void_p,
                                       ctypes.POINTER(_RECT), ctypes.c_double)

            def cb(hmon, hdc, lprc, data):
                mi = _MONITORINFO()
                mi.cbSize = ctypes.sizeof(_MONITORINFO)
                if ctypes.windll.user32.GetMonitorInfoW(hmon, ctypes.byref(mi)):
                    r = mi.rcMonitor
                    out.append((r.left, r.top, r.right, r.bottom))
                return 1
            ctypes.windll.user32.EnumDisplayMonitors(None, None, proto(cb), 0)
        except Exception:
            pass
    elif IS_MAC:
        out.extend(mac_monitors())
    if not out:
        out.append(monitor_at(0, 0))
    out.sort(key=lambda r: (r[1], r[0]))
    return out


def _screens_union(frames, top):
    """NSScreen 프레임 목록을 Tk 좌표의 한 범위로 합친다. → (x, y, w, h)

    맥의 화면 좌표는 **주 화면 왼쪽 아래가 0,0 이고 y 가 위로** 자란다.
    Tk 는 주 화면 왼쪽 위가 0,0 이고 y 가 아래로 자란다. `top` 은 주 화면의
    높이(= NS 좌표에서 주 화면 위쪽 끝)다.

    맥이 없어도 검사할 수 있게 계산만 떼어 두었다.
    """
    if not frames:
        return None
    x0 = min(f[0] for f in frames)
    x1 = max(f[0] + f[2] for f in frames)
    y0 = min(top - (f[1] + f[3]) for f in frames)
    y1 = max(top - f[1] for f in frames)
    return int(x0), int(y0), int(x1 - x0), int(y1 - y0)


def _mac_desktop_rect():
    """맥에서 **모든 화면을 합친** 범위 (Tk 좌표). 못 구하면 None.

    `winfo_screenwidth/vrootwidth` 는 맥에서 **주 화면만** 알려 준다. 그래서
    보조 화면에 둔 창은 '화면 밖'으로 판정되어 저장해 둔 자리가 버려지고,
    켤 때마다 주 화면 기본 자리로 돌아갔다 (사가 제보 — 캐릭터도 환경설정
    창도 같은 이유였다).

    AppKit 은 맥 번들에 반드시 있다 (지뢰 21·57). 실패하면 None 을 돌려
    예전 판정으로 물러난다.
    """
    try:
        from AppKit import NSScreen
        scr = list(NSScreen.screens())
        if not scr:
            return None
        p = scr[0].frame()                      # 첫 번째가 주 화면이다
        top = float(p.origin.y) + float(p.size.height)
        frames = [(float(s.frame().origin.x), float(s.frame().origin.y),
                   float(s.frame().size.width), float(s.frame().size.height))
                  for s in scr]
        return _screens_union(frames, top)
    except Exception:
        return None


def monitor_at(x, y):
    if IS_WIN:
        try:
            hmon = ctypes.windll.user32.MonitorFromPoint(_POINT(x, y), 2)
            mi = _MONITORINFO()
            mi.cbSize = ctypes.sizeof(_MONITORINFO)
            if ctypes.windll.user32.GetMonitorInfoW(hmon, ctypes.byref(mi)):
                r = mi.rcMonitor
                return r.left, r.top, r.right, r.bottom
        except Exception:
            pass
        u = ctypes.windll.user32
        return 0, 0, u.GetSystemMetrics(0), u.GetSystemMetrics(1)
    if IS_MAC:                    # 맥: 점이 들어 있는 화면을 찾는다
        for r in mac_monitors():
            if r[0] <= x < r[2] and r[1] <= y < r[3]:
                return r
    if _TK_ROOT is not None:      # 못 찾으면 주 화면 기준
        try:
            return (0, 0, _TK_ROOT.winfo_screenwidth(),
                    _TK_ROOT.winfo_screenheight())
        except Exception:
            pass
    return 0, 0, 1920, 1080


def monitor_work(x, y):
    """그 점이 놓인 화면의 '작업 영역' (작업표시줄 제외). 창 자리 계산용."""
    if IS_WIN:
        try:
            hmon = ctypes.windll.user32.MonitorFromPoint(_POINT(x, y), 2)
            mi = _MONITORINFO()
            mi.cbSize = ctypes.sizeof(_MONITORINFO)
            if ctypes.windll.user32.GetMonitorInfoW(hmon, ctypes.byref(mi)):
                r = mi.rcWork
                return r.left, r.top, r.right, r.bottom
        except Exception:
            pass
    return monitor_at(x, y)


